/* Bilingual draft questions for course-based comprehension; legacy bank untouched. */
(function(root){if(root)root.PowerOnCourseQuestionBank=[{"id":"NEW_L08_P1_p1_01","lesson":8,"part":1,"paragraph":1,"difficulty":"Basic","skill":"Detail","en":["Which lake is associated with the city of St. Catharines?",["Lake Ontario.","Lake Huron.","Lake Michigan.","Lake Superior."]],"ja":["セントキャサリンズがあるのは、どの湖の近くですか。",["オンタリオ湖","ヒューロン湖","ミシガン湖","スペリオル湖"]],"correct":0,"evidence":"St. Catharines is a small city along the shore of Lake Ontario.","explanation":"本文で町の位置はオンタリオ湖の湖岸とされている。"},{"id":"NEW_L08_P1_p1_02","lesson":8,"part":1,"paragraph":1,"difficulty":"Basic","skill":"Detail","en":["Which well-known natural landmark is near St. Catharines?",["Victoria Falls.","Niagara Falls.","Mount Fuji.","The Grand Canyon."]],"ja":["セントキャサリンズの近くにある有名な自然の名所は何ですか。",["ビクトリアの滝","ナイアガラの滝","富士山","グランドキャニオン"]],"correct":1,"evidence":"The city is close to the world-famous Niagara Falls, which stretches along the border between the U.S. and Canada.","explanation":"本文でナイアガラの滝に近いと説明される。"},{"id":"NEW_L08_P1_p1_03","lesson":8,"part":1,"paragraph":1,"difficulty":"Standard","skill":"Cause/Effect","en":["Why is the chapel significant to the Underground Railroad story?",["It built the border between two countries.","It marked the end of the freedom route described in the text.","It supplied the first railway engines.","It controlled all slave plantations."]],"ja":["その礼拝堂は、地下鉄道の歴史においてなぜ重要なのですか。",["２国間の国境を造ったから","本文で説明される自由への経路の終点だったから","最初の鉄道機関車を供給したから","すべての奴隷農園を支配していたから"]],"correct":1,"evidence":"The chapel was the \"terminal station\" of the \"Underground Railroad.\"","explanation":"礼拝堂は地下鉄道の「終着駅」だった。"},{"id":"NEW_L08_P1_p1_04","lesson":8,"part":1,"paragraph":1,"difficulty":"Standard","skill":"Sequence","en":["Which event happened much later than the chapel's role in the Underground Railroad?",["The establishment of secret stations for escaping people.","People travelling on the route toward freedom.","The Canadian government's 1999 historic-site designation.","The chapel serving as a terminal station."]],"ja":["礼拝堂が地下鉄道で役割を果たした時代より、ずっと後に起きた出来事はどれですか。",["逃亡者のための秘密の停車駅の設置","自由を目指す経路を人々が移動したこと","1999年にカナダ政府がその場所を史跡に指定したこと","礼拝堂が終着地点として機能したこと"]],"correct":2,"evidence":"In 1999, the Canadian government formally chose a small chapel in St. Catharines as a National Historic Site of Canada.","explanation":"史跡への正式指定は1999年で、過去の歴史的役割より後である。"},{"id":"NEW_L08_P1_p1_05","lesson":8,"part":1,"paragraph":1,"difficulty":"Challenge","skill":"Reference","en":["What does the word \"chapel\" refer to in the last two sentences?",["A waterfall on the international border.","A plantation in Maryland.","A small religious building in St. Catharines.","A train operating in Philadelphia."]],"ja":["最後の２文にある「chapel」は何を指しますか。",["国境にある滝","メリーランド州の農園","セントキャサリンズにある小さな宗教施設","フィラデルフィアを走る列車"]],"correct":2,"evidence":"In 1999, the Canadian government formally chose a small chapel in St. Catharines as a National Historic Site of Canada.","explanation":"chapelはセントキャサリンズの小さな礼拝堂を指す。"},{"id":"NEW_L08_P1_p1_06","lesson":8,"part":1,"paragraph":1,"difficulty":"Challenge","skill":"Main Idea","en":["Which description best connects the setting and the history in this paragraph?",["A railroad was opened for tourist trips in 1999.","A lake was built to carry passengers by train.","An American city created a new waterfall.","A Canadian city has a chapel tied to a route to freedom."]],"ja":["この段落の場所と歴史のつながりを最もよく表すものはどれですか。",["観光用の鉄道が1999年に開通した","乗客を列車で運ぶために湖が造られた","アメリカの都市が新しい滝を造った","カナダの都市に、自由への経路に関わった礼拝堂がある"]],"correct":3,"evidence":"In 1999, the Canadian government formally chose a small chapel in St. Catharines as a National Historic Site of Canada.","explanation":"町の紹介から歴史的な礼拝堂へと話題がつながっている。"},{"id":"NEW_L08_P1_p2_01","lesson":8,"part":1,"paragraph":2,"difficulty":"Basic","skill":"Detail","en":["Which group in Philadelphia is given as a specific example of helpers?",["The Normans.","British soldiers.","Quakers.","Slave catchers."]],"ja":["フィラデルフィアで逃亡者を助けた人々の具体例として、どの集団が挙げられていますか。",["ノルマン人","イギリス兵","クエーカー教徒","奴隷追跡者"]],"correct":2,"evidence":"For example, Quakers living in Philadelphia helped them because they strongly believed in human equality.","explanation":"協力者の具体例としてクエーカー教徒が挙げられている。"},{"id":"NEW_L08_P1_p2_02","lesson":8,"part":1,"paragraph":2,"difficulty":"Basic","skill":"Cause/Effect","en":["Why did the Quakers help people escaping slavery?",["They wanted to become slaveholders.","They believed strongly in human equality.","They hoped to stop all religious meetings.","They were building a public train station."]],"ja":["クエーカー教徒は、なぜ奴隷制から逃れる人々を助けたのですか。",["自分たちが奴隷所有者になりたかったから","人間の平等を強く信じていたから","すべての宗教集会をやめさせたかったから","公共の鉄道駅を建設していたから"]],"correct":1,"evidence":"For example, Quakers living in Philadelphia helped them because they strongly believed in human equality.","explanation":"人間の平等を信じていたことが支援の理由である。"},{"id":"NEW_L08_P1_p2_03","lesson":8,"part":1,"paragraph":2,"difficulty":"Standard","skill":"Purpose","en":["Why were lamps placed in station windows?",["To warn owners that their workers had arrived.","To help escaping people identify safe locations.","To make the churches look larger.","To display the time for passenger trains."]],"ja":["秘密の停車駅の窓にランプが置かれたのはなぜですか。",["労働者の到着を所有者に知らせるため","逃亡者が安全な場所を見分けられるようにするため","教会を大きく見せるため","旅客列車の時刻を表示するため"]],"correct":1,"evidence":"The \"stations\" put a lamp in the window so that escaping slaves could find them.","explanation":"ランプは逃亡者が秘密の場所を見つけるための目印だった。"},{"id":"NEW_L08_P1_p2_04","lesson":8,"part":1,"paragraph":2,"difficulty":"Standard","skill":"Inference","en":["What can be inferred about a \"station\" on the Underground Railroad?",["It might be an ordinary house or barn used to shelter people.","It was always a government office.","It had to contain train tracks and ticket counters.","It was usually a place to arrest escapees."]],"ja":["地下鉄道の「station（停車駅）」について、どのようなことが推測できますか。",["人々をかくまう普通の家や納屋だった可能性がある","常に政府の役所だった","必ず線路と切符売り場があった","通常は逃亡者を逮捕する場所だった"]],"correct":0,"evidence":"There, escaping slaves were hidden, warmed, and fed―in homes, barns, and sometimes churches.","explanation":"普通の家や納屋や教会が逃亡者の避難場所となっていた。"},{"id":"NEW_L08_P1_p2_05","lesson":8,"part":1,"paragraph":2,"difficulty":"Challenge","skill":"Contrast","en":["Which statement correctly contrasts Philadelphia and the South in the passage?",["The South was the only location of secret stations.","Philadelphia represented punishment rather than freedom.","Philadelphia represented freedom, while people in the South sought escape.","Philadelphia was where all slave catchers lived, while the South was safe."]],"ja":["本文でのフィラデルフィアと南部の対比として正しいものはどれですか。",["秘密の停車駅は南部にしかなかった","フィラデルフィアは自由ではなく処罰の象徴だった","フィラデルフィアは自由の象徴で、南部の人々は脱出を目指した","フィラデルフィアはすべての奴隷追跡者の居住地で、南部は安全だった"]],"correct":2,"evidence":"In those days, Philadelphia was the symbol of freedom for slaves.","explanation":"フィラデルフィアは自由の象徴であり、南部からそこへ向かった。"},{"id":"NEW_L08_P1_p2_06","lesson":8,"part":1,"paragraph":2,"difficulty":"Challenge","skill":"Sequence","en":["Which sequence matches how the escape network worked?",["Board a public subway, buy a ticket, and return home.","Reach Canada, report to a slaveholder, and travel south.","Find a station without signs, then wait for the Civil War.","Travel north, locate a lamp-marked station, and receive shelter."]],"ja":["逃亡を支えるネットワークの働きを正しい順に示したものはどれですか。",["公共の地下鉄に乗り、切符を買って家に帰る","カナダに着き、奴隷所有者に報告し、南へ向かう","目印のない駅を探し、南北戦争を待つ","北へ向かい、ランプが目印の停車駅を見つけ、かくまってもらう"]],"correct":3,"evidence":"The \"stations\" put a lamp in the window so that escaping slaves could find them.","explanation":"目印となるランプを探し、安全な場所で身を隠して旅を続けた。"},{"id":"NEW_L08_P2_p3_01","lesson":8,"part":2,"paragraph":3,"difficulty":"Basic","skill":"Detail","en":["What was one way information about escape routes was shared?",["Through printed guidebooks given to everyone.","Through daily newspaper advertisements.","Through public notices from slaveholders.","Through songs containing hidden meanings."]],"ja":["逃亡経路に関する情報を共有する方法の一つは何でしたか。",["全員に配られた印刷済みの案内書を通じて","毎日の新聞広告を通じて","奴隷所有者による公の告知を通じて","隠された意味を含む歌を通じて"]],"correct":3,"evidence":"It is said that songs known as Negro spirituals contained secret messages.","explanation":"歌に含まれる秘密の意味によって経路の情報が伝えられた。"},{"id":"NEW_L08_P2_p3_02","lesson":8,"part":2,"paragraph":3,"difficulty":"Basic","skill":"Reference","en":["In the songs described, what did the word \"angels\" represent?",["People who built churches.","The stars above Canada.","The names of American presidents.","Conductors who helped people escape."]],"ja":["本文で紹介された歌の中で「angels」は誰を表していましたか。",["教会を建設する人々","カナダ上空の星","アメリカ大統領の名前","逃亡を助ける案内役"]],"correct":3,"evidence":"For example, \"angels\" meant \"conductors,\" and \"Jordan\" meant \"the Ohio River.\" Slaves sang the spirituals within their families, but not in the presence of white people.","explanation":"angels は逃亡者を助ける案内役を示した。"},{"id":"NEW_L08_P2_p3_03","lesson":8,"part":2,"paragraph":3,"difficulty":"Standard","skill":"Purpose","en":["Why did enslaved people avoid singing these songs in front of white people?",["They wanted the songs to be forgotten.","They needed to keep the hidden messages from being exposed.","They could only sing in official schools.","They were waiting for a public concert."]],"ja":["奴隷にされた人々は、なぜ白人の前でその歌を歌うのを避けたのですか。",["その歌を忘れ去らせたかったから","秘密のメッセージを知られないようにする必要があったから","正式な学校でしか歌えなかったから","公開コンサートを待っていたから"]],"correct":1,"evidence":"For example, \"angels\" meant \"conductors,\" and \"Jordan\" meant \"the Ohio River.\" Slaves sang the spirituals within their families, but not in the presence of white people.","explanation":"歌に含まれる秘密を守るため、白人の前では歌わなかったと読み取れる。"},{"id":"NEW_L08_P2_p3_04","lesson":8,"part":2,"paragraph":3,"difficulty":"Standard","skill":"Cause/Effect","en":["How did the songs help even when many people could not read?",["The messages could be learned and passed on orally.","They automatically gave each traveler a written map.","They changed the law about literacy.","They taught everyone French first."]],"ja":["多くの人が読み書きできなかったにもかかわらず、歌が役立ったのはなぜですか。",["口頭でメッセージを覚えて伝えられたから","旅行者全員に自動的に書かれた地図を渡したから","識字に関する法律を変えたから","最初に全員にフランス語を教えたから"]],"correct":0,"evidence":"Most slaves were not allowed to learn how to read or write.","explanation":"文字を使わなくても歌を通じて情報を伝えられた。"},{"id":"NEW_L08_P2_p3_05","lesson":8,"part":2,"paragraph":3,"difficulty":"Challenge","skill":"Contrast","en":["Which pair shows the contrast at the center of paragraph 3?",["Lake Ontario and Niagara Falls.","The Civil War and the Emancipation Proclamation.","Lack of literacy and the use of songs to communicate.","The North Star and Queen Victoria."]],"ja":["第３段落の中心にある対比を示す組み合わせはどれですか。",["オンタリオ湖とナイアガラの滝","南北戦争と奴隷解放宣言","読み書きできないことと、歌を使った伝達","北極星とビクトリア女王"]],"correct":2,"evidence":"In this way, the slaves learned the routes to freedom.","explanation":"読み書きが制限される一方、歌によって経路を学んだ点が対比される。"},{"id":"NEW_L08_P2_p3_06","lesson":8,"part":2,"paragraph":3,"difficulty":"Challenge","skill":"Main Idea","en":["What is the main point of this paragraph?",["All songs were written by government officials.","Most escaping people used published maps.","Spirituals helped communicate secret information about freedom routes.","Music was performed only in public theatres."]],"ja":["この段落の要点は何ですか。",["すべての歌は政府の役人が書いた","逃亡者の大半は出版された地図を使った","黒人霊歌が自由への経路に関する秘密の情報を伝えるのに役立った","音楽は公開劇場でのみ演奏された"]],"correct":2,"evidence":"It is said that songs known as Negro spirituals contained secret messages.","explanation":"段落の中心は霊歌が秘密の経路情報を伝えたことである。"},{"id":"NEW_L08_P2_p4_01","lesson":8,"part":2,"paragraph":4,"difficulty":"Basic","skill":"Detail","en":["What name is given to Harriet Tubman's role in the escape network?",["A governor.","An engineer of trains.","A slave catcher.","A conductor."]],"ja":["逃亡を支えるネットワークでのハリエット・タブマンの役割は何と呼ばれましたか。",["知事","列車の技師","奴隷追跡者","案内役（車掌）"]],"correct":3,"evidence":"Harriet Tubman was a \"conductor\" who saved more than 300 slaves.","explanation":"本文では案内役の比喩として conductor と呼ぶ。"},{"id":"NEW_L08_P2_p4_02","lesson":8,"part":2,"paragraph":4,"difficulty":"Basic","skill":"Detail","en":["Which number best matches the people Harriet helped save in the passage?",["Exactly ten.","More than three hundred.","Fewer than twenty.","Exactly one hundred."]],"ja":["本文によると、ハリエットが救った人数に最も近いものはどれですか。",["ちょうど10人","300人を超える人数","20人未満","ちょうど100人"]],"correct":1,"evidence":"Harriet Tubman was a \"conductor\" who saved more than 300 slaves.","explanation":"本文は300人を超える人々を救ったとする。"},{"id":"NEW_L08_P2_p4_03","lesson":8,"part":2,"paragraph":4,"difficulty":"Standard","skill":"Detail","en":["Which state is named as Harriet's birthplace?",["Maryland.","Ohio.","New York.","Virginia."]],"ja":["ハリエットの出生地として挙げられている州はどれですか。",["メリーランド州","オハイオ州","ニューヨーク州","バージニア州"]],"correct":0,"evidence":"She was born into slavery on a plantation in Maryland around 1820.","explanation":"出身地はメリーランド州である。"},{"id":"NEW_L08_P2_p4_04","lesson":8,"part":2,"paragraph":4,"difficulty":"Standard","skill":"Detail","en":["Approximately when was Harriet born, according to the passage?",["Around 2011.","Around 1999.","Around 1820.","Around 1863."]],"ja":["本文によると、ハリエットがおよそ生まれたのはいつですか。",["2011年ごろ","1999年ごろ","1820年ごろ","1863年ごろ"]],"correct":2,"evidence":"She was born into slavery on a plantation in Maryland around 1820.","explanation":"出生年は1820年ごろと記述されている。"},{"id":"NEW_L08_P2_p4_05","lesson":8,"part":2,"paragraph":4,"difficulty":"Challenge","skill":"Detail","en":["How many brothers and sisters did Harriet have?",["Three.","Twelve.","Two.","Ten."]],"ja":["ハリエットには何人の兄弟姉妹がいましたか。",["３人","12人","２人","10人"]],"correct":3,"evidence":"She had ten brothers and sisters.","explanation":"兄弟姉妹は10人と本文にある。"},{"id":"NEW_L08_P2_p4_06","lesson":8,"part":2,"paragraph":4,"difficulty":"Challenge","skill":"Inference","en":["Which statement about Harriet's early life is directly supported?",["She was born into slavery before becoming a guide to freedom.","She was born after the Civil War.","She first learned about slavery as an adult.","She was born in Canada and later moved to Maryland."]],"ja":["ハリエットの幼少期について、本文から直接分かることはどれですか。",["奴隷として生まれ、後に自由への案内役になった","南北戦争後に生まれた","大人になって初めて奴隷制を知った","カナダで生まれ、後にメリーランド州へ移った"]],"correct":0,"evidence":"She was born into slavery on a plantation in Maryland around 1820.","explanation":"奴隷として生まれ、その後自由への案内役になったことが分かる。"},{"id":"NEW_L08_P2_p5_01","lesson":8,"part":2,"paragraph":5,"difficulty":"Basic","skill":"Sequence","en":["What happened soon after Harriet's owner died?",["She returned from Canada with passengers.","She was honored by Queen Victoria.","She received the Emancipation Proclamation.","She heard that she and two brothers would be sold."]],"ja":["ハリエットの所有者が亡くなった後、間もなく何が起こりましたか。",["カナダから仲間と帰ってきた","ビクトリア女王から表彰された","奴隷解放宣言を受け取った","自分と兄弟２人が売られると聞いた"]],"correct":3,"evidence":"A few years later, her owner died.","explanation":"所有者の死後、自分たちが売られることを聞いた。"},{"id":"NEW_L08_P2_p5_02","lesson":8,"part":2,"paragraph":5,"difficulty":"Basic","skill":"Purpose","en":["Why did Harriet and her brothers cross a river during their escape?",["To reach a market where they could be sold.","To prevent dogs from following their trail.","To board a train waiting on the other bank.","To meet their former owner."]],"ja":["ハリエットと兄弟たちは、逃亡中になぜ川を渡ったのですか。",["売られる市場へ着くため","犬に追跡されないようにするため","対岸で待つ列車に乗るため","以前の所有者に会うため"]],"correct":1,"evidence":"That night, they fled from the plantation, and crossed a river so that the dogs could not follow them.","explanation":"川を渡ったのは追跡する犬をまくためである。"},{"id":"NEW_L08_P2_p5_03","lesson":8,"part":2,"paragraph":5,"difficulty":"Standard","skill":"Contrast","en":["What did Harriet do differently from her brothers before dawn?",["She returned while they kept walking north.","She continued while they returned to the slave huts.","She asked them to carry her back home.","She hid in a church while they went to Canada."]],"ja":["夜明け前、ハリエットは兄弟たちと違って何をしましたか。",["彼女が戻り、兄弟たちが北へ歩き続けた","兄弟たちが奴隷小屋に戻る一方で、彼女は進み続けた","兄弟たちに自分を家へ運び戻すよう頼んだ","兄弟たちがカナダへ行く間、彼女は教会に隠れた"]],"correct":1,"evidence":"Before dawn, her brothers became so frightened that they went back to the slave huts, but Harriet never gave up her hope.","explanation":"兄弟は引き返したが、ハリエットは進み続けた。"},{"id":"NEW_L08_P2_p5_04","lesson":8,"part":2,"paragraph":5,"difficulty":"Standard","skill":"Sequence","en":["When did Harriet travel through the woods after being left alone?",["Only when her brothers were beside her.","Only at noon.","At night, while hiding during the day.","In the morning, while sleeping each night."]],"ja":["一人になったハリエットは、いつ森を通って移動しましたか。",["兄弟たちがそばにいる時だけ","正午だけ","夜に移動し、昼間は隠れた","朝に移動し、毎晩眠った"]],"correct":2,"evidence":"She went on alone through the woods by night.","explanation":"夜に進み、昼に隠れていた。"},{"id":"NEW_L08_P2_p5_05","lesson":8,"part":2,"paragraph":5,"difficulty":"Challenge","skill":"Inference","en":["What provided Harriet with direction despite having no map?",["A railroad conductor's ticket.","The North Star.","A guidebook from the owner.","A written timetable."]],"ja":["地図を持たないハリエットが方向を知る手がかりになったのは何ですか。",["鉄道の車掌の切符","北極星","所有者からもらった案内書","書かれた時刻表"]],"correct":1,"evidence":"She used the North Star to guide her.","explanation":"地図を持たないハリエットは北極星を頼りに進んだ。"},{"id":"NEW_L08_P2_p5_06","lesson":8,"part":2,"paragraph":5,"difficulty":"Challenge","skill":"Character","en":["Which quality is best supported by Harriet's decision to continue alone?",["Willingness to give up quickly.","Desire to remain on the plantation.","Determination despite danger.","Fear of travelling without her brothers."]],"ja":["一人でも進み続けたハリエットの決断から、どのような性格が読み取れますか。",["すぐに諦めようとする態度","農園に残りたいという願い","危険にも負けない決意","兄弟なしで旅をすることへの恐怖"]],"correct":2,"evidence":"Before dawn, her brothers became so frightened that they went back to the slave huts, but Harriet never gave up her hope.","explanation":"危険を冒しても希望を捨てなかった点は強い決意を示す。"},{"id":"NEW_L08_P3_p6_01","lesson":8,"part":3,"paragraph":6,"difficulty":"Basic","skill":"Contrast","en":["Why was Harriet unhappy even though she was no longer enslaved?",["She had been made a slave catcher.","Her family members remained enslaved.","She had lost her silver medal.","She was unable to visit Niagara Falls."]],"ja":["ハリエットは奴隷でなくなったのに、なぜ幸せを感じられなかったのですか。",["奴隷追跡者にされたから","家族がまだ奴隷のままだったから","銀メダルをなくしたから","ナイアガラの滝を訪ねられなかったから"]],"correct":1,"evidence":"All her family members were still slaves.","explanation":"自分は自由でも家族が奴隷のままだったため幸せを感じられなかった。"},{"id":"NEW_L08_P3_p6_02","lesson":8,"part":3,"paragraph":6,"difficulty":"Basic","skill":"Sequence","en":["Where did Harriet return some months after gaining freedom?",["St. Catharines.","Maryland.","New York City.","London."]],"ja":["自由を得てから数か月後、ハリエットはどこへ戻りましたか。",["セントキャサリンズ","メリーランド州","ニューヨーク市","ロンドン"]],"correct":1,"evidence":"Some months later, she went back to Maryland and met her family again.","explanation":"数か月後にメリーランドへ戻った。"},{"id":"NEW_L08_P3_p6_03","lesson":8,"part":3,"paragraph":6,"difficulty":"Standard","skill":"Detail","en":["Whom did Harriet hope would travel north with her?",["Queen Victoria.","Her husband.","Abraham Lincoln.","The Canadian governor."]],"ja":["ハリエットは誰に一緒に北へ行ってほしいと望みましたか。",["ビクトリア女王","夫","エイブラハム・リンカーン","カナダの知事"]],"correct":1,"evidence":"She hoped that her husband would come north with her.","explanation":"夫が一緒に北へ向かうことを望んだ。"},{"id":"NEW_L08_P3_p6_04","lesson":8,"part":3,"paragraph":6,"difficulty":"Standard","skill":"Contrast","en":["How did Harriet's husband respond to her hope?",["He decided to become a slave catcher.","He promised to build a new railroad.","He immediately went north with her.","He did not want to go."]],"ja":["ハリエットの夫は、彼女の希望にどう答えましたか。",["奴隷追跡者になると決めた","新しい鉄道を建設すると約束した","すぐに一緒に北へ行った","行きたくないと言った"]],"correct":3,"evidence":"However, he said he did not wish to go.","explanation":"夫は一緒に行くことを望まなかった。"},{"id":"NEW_L08_P3_p6_05","lesson":8,"part":3,"paragraph":6,"difficulty":"Challenge","skill":"Detail","en":["Who was included among the people Harriet led north afterward?",["Only two government officers.","Queen Victoria and her attendants.","Only her husband and his friends.","Two brothers, a sister, her children, and more enslaved people."]],"ja":["その後、ハリエットが北へ導いた人々には誰が含まれていましたか。",["政府の役人２人だけ","ビクトリア女王とその付き人","夫とその友人だけ","兄弟２人と姉妹１人、その子どもたち、さらに奴隷にされた人々"]],"correct":3,"evidence":"So she led two brothers, a sister, her children, and a dozen more slaves to the North.","explanation":"本文は兄弟2人、姉妹1人、その子どもたち、ほか約12人を挙げる。"},{"id":"NEW_L08_P3_p6_06","lesson":8,"part":3,"paragraph":6,"difficulty":"Challenge","skill":"Inference","en":["What does Harriet's return to Maryland suggest about her motivation?",["She wanted to help her family reach freedom as well.","She hoped to buy a new plantation.","She was searching for a reward offered by slaveholders.","She wanted to abandon her earlier escape."]],"ja":["ハリエットがメリーランド州に戻ったことから、どんな動機が読み取れますか。",["家族にも自由を手に入れてほしかった","新しい農園を買いたかった","奴隷所有者が提示した報奨金を探していた","以前の逃亡を諦めたかった"]],"correct":0,"evidence":"She kept thinking about them.","explanation":"家族を忘れられず、救出のために戻ったと読み取れる。"},{"id":"NEW_L08_P3_p7_01","lesson":8,"part":3,"paragraph":7,"difficulty":"Basic","skill":"Detail","en":["What law made helping escaping people illegal in the passage?",["The Fugitive Slave Law of 1850.","A Canadian law enacted in 1999.","The Emancipation Proclamation of 1863.","The Oxford Dictionary Act."]],"ja":["本文で、逃亡者を助けることを違法にした法律は何ですか。",["1850年の逃亡奴隷法","1999年制定のカナダの法律","1863年の奴隷解放宣言","オックスフォード辞典法"]],"correct":0,"evidence":"The Fugitive Slave Law of 1850, which prohibited anyone from helping escaping slaves, now made it dangerous for runaways to stop anywhere in the U.S. So Harriet led her followers to Canada, where they would be safe and free.","explanation":"1850年の逃亡奴隷取締法が支援を禁止した。"},{"id":"NEW_L08_P3_p7_02","lesson":8,"part":3,"paragraph":7,"difficulty":"Basic","skill":"Detail","en":["Which action did the law prohibit?",["Building chapels in Canadian towns.","Helping people escaping slavery.","Writing songs with hidden messages.","Crossing Lake Ontario by boat."]],"ja":["その法律は、どのような行為を禁止しましたか。",["カナダの町に礼拝堂を建てること","奴隷制から逃れる人々を助けること","秘密のメッセージを含む歌を書くこと","オンタリオ湖を船で渡ること"]],"correct":1,"evidence":"The Fugitive Slave Law of 1850, which prohibited anyone from helping escaping slaves, now made it dangerous for runaways to stop anywhere in the U.S. So Harriet led her followers to Canada, where they would be safe and free.","explanation":"逃亡者を助けることが禁じられた。"},{"id":"NEW_L08_P3_p7_03","lesson":8,"part":3,"paragraph":7,"difficulty":"Standard","skill":"Cause/Effect","en":["Why did stopping anywhere in the United States become dangerous for escapees?",["The North Star became impossible to see.","Canada had closed its border to everyone.","The law threatened people who helped them.","All churches had been destroyed."]],"ja":["なぜアメリカ国内のどこかに留まることが逃亡者にとって危険になったのですか。",["北極星が見えなくなったから","カナダが全員に対して国境を閉ざしたから","助けた人々も法律で処罰されるおそれがあったから","すべての教会が破壊されたから"]],"correct":2,"evidence":"The Fugitive Slave Law of 1850, which prohibited anyone from helping escaping slaves, now made it dangerous for runaways to stop anywhere in the U.S. So Harriet led her followers to Canada, where they would be safe and free.","explanation":"支援者にも危険が及ぶ法律のため米国内での滞在が危険になった。"},{"id":"NEW_L08_P3_p7_04","lesson":8,"part":3,"paragraph":7,"difficulty":"Standard","skill":"Destination","en":["To which country did Harriet lead her followers in response?",["Canada.","Germany.","Italy.","France."]],"ja":["その状況を受けて、ハリエットは仲間をどの国へ導きましたか。",["カナダ","ドイツ","イタリア","フランス"]],"correct":0,"evidence":"The Fugitive Slave Law of 1850, which prohibited anyone from helping escaping slaves, now made it dangerous for runaways to stop anywhere in the U.S. So Harriet led her followers to Canada, where they would be safe and free.","explanation":"ハリエットは安全と自由を求めカナダへ導いた。"},{"id":"NEW_L08_P3_p7_05","lesson":8,"part":3,"paragraph":7,"difficulty":"Challenge","skill":"Inference","en":["Why was crossing an international border important in this part of the story?",["It let the travelers collect payment from slaveholders.","Canada was presented as a place where the followers would be safe and free.","The followers had been ordered to return to Maryland.","The passage says the North Star could only be seen there."]],"ja":["物語のこの部分で、国境を越えることが重要だったのはなぜですか。",["奴隷所有者から支払いを受けられたから","カナダは仲間が安全に自由に暮らせる場所として描かれていたから","仲間はメリーランド州へ戻るよう命令されていたから","北極星はそこからしか見えないと本文にあるから"]],"correct":1,"evidence":"The Fugitive Slave Law of 1850, which prohibited anyone from helping escaping slaves, now made it dangerous for runaways to stop anywhere in the U.S. So Harriet led her followers to Canada, where they would be safe and free.","explanation":"本文の対比は米国内の危険とカナダでの安全・自由である。"},{"id":"NEW_L08_P3_p7_06","lesson":8,"part":3,"paragraph":7,"difficulty":"Challenge","skill":"Cause/Effect","en":["Which cause-and-effect relationship is explicitly described?",["Niagara Falls froze, so escapees walked south.","An award was announced, so Harriet stopped helping people.","The proclamation was signed, so the chapel closed.","A stricter law increased danger, so Harriet led people to Canada."]],"ja":["本文で明確に述べられている原因と結果の関係はどれですか。",["ナイアガラの滝が凍ったため、逃亡者は南へ歩いた","表彰が発表されたため、ハリエットは救助をやめた","宣言が署名されたため、礼拝堂が閉鎖された","厳しい法律によって危険が増えたため、ハリエットは人々をカナダへ導いた"]],"correct":3,"evidence":"The Fugitive Slave Law of 1850, which prohibited anyone from helping escaping slaves, now made it dangerous for runaways to stop anywhere in the U.S. So Harriet led her followers to Canada, where they would be safe and free.","explanation":"危険が高まった結果、カナダへ向かったという因果関係である。"},{"id":"NEW_L08_P3_p8_01","lesson":8,"part":3,"paragraph":8,"difficulty":"Basic","skill":"Character","en":["What reputation spread about Harriet?",["That she was a fearless leader.","That she was a government lawyer.","That she was a wealthy slaveholder.","That she was a railroad engineer."]],"ja":["ハリエットについてどのような評判が広まりましたか。",["恐れを知らない指導者だという評判","政府の弁護士だという評判","裕福な奴隷所有者だという評判","鉄道技師だという評判"]],"correct":0,"evidence":"Harriet's reputation as a fearless leader spread fast.","explanation":"恐れを知らない指導者としての評判が広がった。"},{"id":"NEW_L08_P3_p8_02","lesson":8,"part":3,"paragraph":8,"difficulty":"Basic","skill":"Cause/Effect","en":["Why did slaveholders offer large rewards?",["They wanted to pay her for helping their families.","They wanted her to become a famous singer.","They wanted to finance new chapels.","They wanted Harriet to be caught."]],"ja":["奴隷所有者が高額の報奨金を出したのはなぜですか。",["自分たちの家族を助けた報酬を払いたかったから","有名な歌手にしたかったから","新しい礼拝堂の建設資金を出したかったから","ハリエットを捕まえたかったから"]],"correct":3,"evidence":"Large rewards were offered by slaveholders for catching her.","explanation":"奴隷主は彼女を捕えるために賞金を出した。"},{"id":"NEW_L08_P3_p8_03","lesson":8,"part":3,"paragraph":8,"difficulty":"Standard","skill":"Detail","en":["What happened when slave catchers tried to capture Harriet?",["They appointed her as an official conductor.","They never captured her.","They caught her every time.","They brought her to Queen Victoria."]],"ja":["奴隷追跡者たちがハリエットを捕まえようとしたとき、何が起こりましたか。",["公式の案内役に任命された","彼女は一度も捕まらなかった","毎回捕まった","ビクトリア女王のもとへ連れていかれた"]],"correct":1,"evidence":"However, she was never captured by slave catchers, and she never lost any of her \"passengers\" to them either, on the way to freedom along the \"Underground Railroad.\"","explanation":"捕獲者に捕まることはなかった。"},{"id":"NEW_L08_P3_p8_04","lesson":8,"part":3,"paragraph":8,"difficulty":"Standard","skill":"Reference","en":["Who are Harriet's \"passengers\" in this paragraph?",["People who rode a commercial subway.","Officials of the Canadian government.","Tourists visiting Niagara Falls.","People she guided toward freedom."]],"ja":["この段落にあるハリエットの「passengers（乗客）」とは誰のことですか。",["商業用の地下鉄に乗った人々","カナダ政府の役人","ナイアガラの滝を訪れる観光客","彼女が自由へ向けて導いた人々"]],"correct":3,"evidence":"However, she was never captured by slave catchers, and she never lost any of her \"passengers\" to them either, on the way to freedom along the \"Underground Railroad.\"","explanation":"passengers は逃亡を手助けした人々の比喩である。"},{"id":"NEW_L08_P3_p8_05","lesson":8,"part":3,"paragraph":8,"difficulty":"Challenge","skill":"Inference","en":["What does \"never lost any of her passengers\" suggest?",["The people travelling with her were not taken by slave catchers.","She carried everyone on a public train.","Her group had never encountered danger.","The travelers never lost their luggage."]],"ja":["「never lost any of her passengers」は、どのようなことを示していますか。",["同行者が奴隷追跡者に捕まらなかったこと","全員を公共の列車で運んだこと","一行が危険に遭ったことは一度もないこと","旅行者が荷物をなくさなかったこと"]],"correct":0,"evidence":"However, she was never captured by slave catchers, and she never lost any of her \"passengers\" to them either, on the way to freedom along the \"Underground Railroad.\"","explanation":"この文脈では捕獲者に仲間を奪われなかったという意味。"},{"id":"NEW_L08_P3_p8_06","lesson":8,"part":3,"paragraph":8,"difficulty":"Challenge","skill":"Main Idea","en":["Which statement best summarizes this paragraph?",["Every passenger had to pay for a train ticket.","Harriet was caught but soon released by slaveholders.","Harriet stopped leading people when rewards appeared.","Even with rewards offered for her capture, Harriet kept her group safe from capture."]],"ja":["この段落の要約として最も適切なものはどれですか。",["すべての乗客が列車の切符を買う必要があった","ハリエットは捕まったが、すぐに奴隷所有者に解放された","報奨金が出ると、ハリエットは案内をやめた","捕獲に報奨金がかけられても、ハリエットは仲間を捕まらないよう守った"]],"correct":3,"evidence":"However, she was never captured by slave catchers, and she never lost any of her \"passengers\" to them either, on the way to freedom along the \"Underground Railroad.\"","explanation":"高額の賞金が懸けられても本人も同行者も捕まらなかった。"},{"id":"NEW_L08_P4_p9_01","lesson":8,"part":4,"paragraph":9,"difficulty":"Basic","skill":"Detail","en":["Who signed the Emancipation Proclamation mentioned here?",["Queen Victoria.","A Canadian prime minister.","Abraham Lincoln.","Harriet Tubman."]],"ja":["ここで述べられる奴隷解放宣言に署名したのは誰ですか。",["ビクトリア女王","カナダの首相","エイブラハム・リンカーン","ハリエット・タブマン"]],"correct":2,"evidence":"Harriet was over forty years old when Abraham Lincoln signed the Emancipation Proclamation in 1863.","explanation":"署名したのはエイブラハム・リンカーンである。"},{"id":"NEW_L08_P4_p9_02","lesson":8,"part":4,"paragraph":9,"difficulty":"Basic","skill":"Detail","en":["In which year did the signing take place?",["1850.","1897.","1863.","2011."]],"ja":["その署名は何年に行われましたか。",["1850年","1897年","1863年","2011年"]],"correct":2,"evidence":"Harriet was over forty years old when Abraham Lincoln signed the Emancipation Proclamation in 1863.","explanation":"本文では1863年と記される。"},{"id":"NEW_L08_P4_p9_03","lesson":8,"part":4,"paragraph":9,"difficulty":"Standard","skill":"Detail","en":["Approximately how old was Harriet at that time?",["In her early twenties.","Over forty.","Under ten.","In her early nineties."]],"ja":["当時、ハリエットはおよそ何歳でしたか。",["20代前半だった","40歳を超えていた","10歳未満だった","90代前半だった"]],"correct":1,"evidence":"Harriet was over forty years old when Abraham Lincoln signed the Emancipation Proclamation in 1863.","explanation":"署名当時、ハリエットは40歳を超えていた。"},{"id":"NEW_L08_P4_p9_04","lesson":8,"part":4,"paragraph":9,"difficulty":"Standard","skill":"Cause/Effect","en":["What did the Emancipation Proclamation change according to the text?",["It created the first secret stations.","It awarded Harriet a silver medal.","It moved Philadelphia to Canada.","It made freedom into a matter of law."]],"ja":["本文によると、奴隷解放宣言は何を変えましたか。",["最初の秘密の停車駅を造った","ハリエットに銀メダルを授けた","フィラデルフィアをカナダに移した","自由を法律によって認められるものにした"]],"correct":3,"evidence":"It turned the freedom she had desperately worked for into a law.","explanation":"彼女が求めた自由が法律となったことが述べられている。"},{"id":"NEW_L08_P4_p9_05","lesson":8,"part":4,"paragraph":9,"difficulty":"Challenge","skill":"Inference","en":["Which statement best describes Harriet's work in relation to the proclamation?",["She had never worked for freedom before 1863.","She began her work only after receiving an award in 1897.","She had been working for freedom before the proclamation was signed.","She wrote the proclamation herself."]],"ja":["奴隷解放宣言との関係で、ハリエットの活動を最もよく表すものはどれですか。",["1863年以前は自由のために活動したことがなかった","1897年に表彰されてから初めて活動を始めた","宣言が署名される前から自由のために活動していた","自分自身で宣言を書いた"]],"correct":2,"evidence":"It turned the freedom she had desperately worked for into a law.","explanation":"布告より前から自由のために尽力していたと分かる。"},{"id":"NEW_L08_P4_p9_06","lesson":8,"part":4,"paragraph":9,"difficulty":"Challenge","skill":"Main Idea","en":["Why is 1863 presented as an important turning point?",["It was the year Harriet reached Philadelphia alone.","It was the year Harriet was born.","The goal Harriet had long pursued was given legal recognition.","It was the first time the chapel was designated a historic site."]],"ja":["1863年が重要な転機として示されているのはなぜですか。",["ハリエットが一人でフィラデルフィアに着いた年だから","ハリエットが生まれた年だから","ハリエットが長く追い求めてきた目標が法的に認められたから","礼拝堂が初めて史跡に指定された年だから"]],"correct":2,"evidence":"It turned the freedom she had desperately worked for into a law.","explanation":"ハリエットの長年の目標が法として認められたことが節目である。"},{"id":"NEW_L08_P4_p10_01","lesson":8,"part":4,"paragraph":10,"difficulty":"Basic","skill":"Detail","en":["For what kind of work was Harriet honored?",["Restaurant management.","Scientific research.","Humanitarian work.","Railway engineering."]],"ja":["ハリエットはどのような活動で称えられましたか。",["レストラン経営","科学研究","人道的活動","鉄道技術"]],"correct":2,"evidence":"Harriet was honored by many people for her humanitarian work.","explanation":"人道的な活動によって称えられた。"},{"id":"NEW_L08_P4_p10_02","lesson":8,"part":4,"paragraph":10,"difficulty":"Basic","skill":"Detail","en":["Who gave Harriet a silver medal for bravery?",["Queen Victoria.","Abraham Lincoln.","The Normans.","The mayor of Philadelphia."]],"ja":["ハリエットに勇敢さを称える銀メダルを贈ったのは誰ですか。",["ビクトリア女王","エイブラハム・リンカーン","ノルマン人","フィラデルフィア市長"]],"correct":0,"evidence":"For example, she was awarded a silver medal for bravery by Queen Victoria in 1897.","explanation":"ヴィクトリア女王から銀メダルを授与されたとある。"},{"id":"NEW_L08_P4_p10_03","lesson":8,"part":4,"paragraph":10,"difficulty":"Standard","skill":"Detail","en":["When was the silver medal awarded?",["1850.","1820.","1897.","2011."]],"ja":["銀メダルが授与されたのはいつですか。",["1850年","1820年","1897年","2011年"]],"correct":2,"evidence":"For example, she was awarded a silver medal for bravery by Queen Victoria in 1897.","explanation":"授与された年は1897年。"},{"id":"NEW_L08_P4_p10_04","lesson":8,"part":4,"paragraph":10,"difficulty":"Standard","skill":"Detail","en":["What is the date of Harriet's death in the passage?",["March 10, 1913.","March 10, 1897.","May 27, 2011.","January 1, 1863."]],"ja":["本文にあるハリエットの命日はいつですか。",["1913年3月10日","1897年3月10日","2011年5月27日","1863年1月1日"]],"correct":0,"evidence":"She died on March 10, 1913, in her early nineties.","explanation":"亡くなったのは1913年3月10日。"},{"id":"NEW_L08_P4_p10_05","lesson":8,"part":4,"paragraph":10,"difficulty":"Challenge","skill":"Detail","en":["What was unveiled in St. Catharines in 2011?",["A new railway locomotive.","A silver medal for President Lincoln.","The North Star.","A plaque honoring Harriet."]],"ja":["2011年にセントキャサリンズで除幕されたのは何ですか。",["新しい鉄道機関車","リンカーン大統領のための銀メダル","北極星","ハリエットを称える銘板"]],"correct":3,"evidence":"On May 27, 2011, a plaque was unveiled in the chapel of St. Catharines to honor Harriet Tubman as a National Historic Person.","explanation":"2011年に除幕されたのはハリエットを称える銘板である。"},{"id":"NEW_L08_P4_p10_06","lesson":8,"part":4,"paragraph":10,"difficulty":"Challenge","skill":"Sequence","en":["Which order of events is correct?",["Plaque, medal, Harriet's death.","Harriet's death, plaque, medal.","Medal, plaque, Harriet's death.","Silver medal, Harriet's death, commemorative plaque."]],"ja":["出来事の正しい順序はどれですか。",["銘板、メダル、ハリエットの死去","ハリエットの死去、銘板、メダル","メダル、銘板、ハリエットの死去","銀メダルの授与、ハリエットの死去、記念銘板"]],"correct":3,"evidence":"On May 27, 2011, a plaque was unveiled in the chapel of St. Catharines to honor Harriet Tubman as a National Historic Person.","explanation":"1897年の授賞、1913年の死、2011年の銘板という順序である。"},{"id":"NEW_L09_P1_p1_01","lesson":9,"part":1,"paragraph":1,"difficulty":"Basic","skill":"Detail","en":["How many volumes does the Oxford English Dictionary have in the passage?",["Two.","Twenty.","One hundred.","Five."]],"ja":["本文にあるオックスフォード英語辞典は何巻構成ですか。",["２巻","20巻","100巻","５巻"]],"correct":1,"evidence":"In fact, the 20-volume Oxford English Dictionary contains about 600,000 entries.","explanation":"本文で紹介される辞書は全20巻である。"},{"id":"NEW_L09_P1_p1_02","lesson":9,"part":1,"paragraph":1,"difficulty":"Basic","skill":"Detail","en":["Approximately how many entries does that dictionary contain?",["Exactly 20,000.","About 6,000.","About 600,000.","About six million."]],"ja":["その辞典には、およそ何項目が収録されていますか。",["ちょうど２万項目","約6千項目","約60万項目","約600万項目"]],"correct":2,"evidence":"In fact, the 20-volume Oxford English Dictionary contains about 600,000 entries.","explanation":"収録見出し語は約60万と述べられている。"},{"id":"NEW_L09_P1_p1_03","lesson":9,"part":1,"paragraph":1,"difficulty":"Standard","skill":"Inference","en":["What does the large dictionary illustrate about English?",["It has only 20 different words.","It has completely stopped changing.","It already has a very large vocabulary.","Its vocabulary is smaller than German's."]],"ja":["この大きな辞典は、英語のどのような特徴を示していますか。",["異なる単語が20個しかないこと","変化を完全にやめたこと","すでに非常に豊富な語彙があること","ドイツ語より語彙が少ないこと"]],"correct":2,"evidence":"English has a huge vocabulary.","explanation":"大規模な辞書は英語の語彙が非常に豊富であることを示す。"},{"id":"NEW_L09_P1_p1_04","lesson":9,"part":1,"paragraph":1,"difficulty":"Standard","skill":"Contrast","en":["What idea does \"Nevertheless\" introduce?",["No one uses English outside Britain.","English no longer borrows words.","English continues to gain words despite its large vocabulary.","The dictionary contains fewer entries than before."]],"ja":["「Nevertheless（それにもかかわらず）」は、どのような考えを導入していますか。",["イギリス以外では誰も英語を使わない","英語はもう借用語を受け入れない","語彙が豊富でも英語には新しい単語が増え続けている","辞典の項目数が以前より少なくなった"]],"correct":2,"evidence":"Nevertheless, English is still growing and adding more words.","explanation":"すでに語彙が多いのに、それでも増え続けているという逆接。"},{"id":"NEW_L09_P1_p1_05","lesson":9,"part":1,"paragraph":1,"difficulty":"Challenge","skill":"Detail","en":["What is happening to English vocabulary according to the paragraph?",["More words are being added.","New entries are no longer possible.","The dictionary has stopped publication.","All existing words are disappearing."]],"ja":["この段落によると、英語の語彙には何が起きていますか。",["新しい単語が増え続けている","新しい項目はもう追加できない","辞典の刊行が停止した","既存の単語がすべて消えつつある"]],"correct":0,"evidence":"Nevertheless, English is still growing and adding more words.","explanation":"英語に新しい語が加わっている。"},{"id":"NEW_L09_P1_p1_06","lesson":9,"part":1,"paragraph":1,"difficulty":"Challenge","skill":"Main Idea","en":["Which title best matches the first paragraph?",["The History of German Pronunciation.","How to Publish a Twenty-Volume Book.","A Large but Still Growing Vocabulary.","Why English Has No New Words."]],"ja":["第１段落に最もふさわしい題名はどれですか。",["ドイツ語の発音の歴史","20巻の本の出版方法","豊富でありながら増え続ける語彙","英語に新語がない理由"]],"correct":2,"evidence":"Nevertheless, English is still growing and adding more words.","explanation":"大きな語彙を持ちながらも成長を続けることが主題。"},{"id":"NEW_L09_P1_p2_01","lesson":9,"part":1,"paragraph":2,"difficulty":"Basic","skill":"Detail","en":["Which language was English similar to until the eleventh century?",["Japanese.","Spanish.","German.","Italian."]],"ja":["11世紀まで英語と似ていたのはどの言語ですか。",["日本語","スペイン語","ドイツ語","イタリア語"]],"correct":2,"evidence":"English and German were similar languages up until the 11th century.","explanation":"11世紀まで英語と類似していた言語はドイツ語。"},{"id":"NEW_L09_P1_p2_02","lesson":9,"part":1,"paragraph":2,"difficulty":"Basic","skill":"Chronology","en":["From which year did many French words start entering English?",["1066.","1999.","1600.","1863."]],"ja":["多くのフランス語の単語が英語に入り始めたのは何年からですか。",["1066年","1999年","1600年","1863年"]],"correct":0,"evidence":"But from 1066, lots of French words began coming into English.","explanation":"フランス語由来語の流入が増えた起点は1066年。"},{"id":"NEW_L09_P1_p2_03","lesson":9,"part":1,"paragraph":2,"difficulty":"Standard","skill":"Cause/Effect","en":["Why did French words become more common in English?",["The Renaissance ended all Latin study.","The French-speaking Normans came to control England.","The Oxford dictionary was shortened.","German became the official language of France."]],"ja":["なぜ英語でフランス語由来の単語が増えたのですか。",["ルネサンスによってラテン語の学習がすべて終わったから","フランス語を話すノルマン人がイングランドを支配するようになったから","オックスフォード辞典が短縮されたから","ドイツ語がフランスの公用語になったから"]],"correct":1,"evidence":"This was because French-speaking people, the Normans, had come to control England.","explanation":"ノルマン人がイングランドを支配したことが理由。"},{"id":"NEW_L09_P1_p2_04","lesson":9,"part":1,"paragraph":2,"difficulty":"Standard","skill":"Detail","en":["In which areas did French words increase greatly?",["Politics, economics, and culture.","Only sports and medicine.","Only astronomy and agriculture.","Only cooking in Canada."]],"ja":["フランス語由来の単語はどの分野で大きく増えましたか。",["政治・経済・文化","スポーツと医学だけ","天文学と農業だけ","カナダの料理だけ"]],"correct":0,"evidence":"In politics, economics, and culture, the number of French words that came into English increased greatly.","explanation":"政治・経済・文化分野で流入が増加した。"},{"id":"NEW_L09_P1_p2_05","lesson":9,"part":1,"paragraph":2,"difficulty":"Challenge","skill":"Example","en":["Which pair of food words does the passage use instead of \"cow\" and \"pig\" at a restaurant?",["Cheese and bread.","Beef and pork.","Rice and noodles.","Fish and chicken."]],"ja":["レストランで「cow」「pig」の代わりに使う食べ物の語として挙げられる組み合わせはどれですか。",["チーズとパン","beef（牛肉）とpork（豚肉）","米と麺","魚と鶏肉"]],"correct":1,"evidence":"For example, we do not sit down at a restaurant and say, \"I'd like cow, please, and my friend will have pig.\" Instead, we order beef and pork.","explanation":"食事の注文では beef と pork が例示される。"},{"id":"NEW_L09_P1_p2_06","lesson":9,"part":1,"paragraph":2,"difficulty":"Challenge","skill":"Inference","en":["What does the restaurant example show?",["English has never borrowed food words.","English uses French-influenced words in everyday situations.","Restaurant language is unrelated to language history.","The passage encourages ordering live animals."]],"ja":["レストランの例から何が分かりますか。",["英語は食べ物の語を借りたことがない","英語は日常の場面でもフランス語の影響を受けた語を使う","レストランの言葉と語史には関係がない","本文は生きた動物を注文するよう勧めている"]],"correct":1,"evidence":"For example, we do not sit down at a restaurant and say, \"I'd like cow, please, and my friend will have pig.\" Instead, we order beef and pork.","explanation":"借用語の影響が日常の食事の語彙に現れることを示す。"},{"id":"NEW_L09_P2_p3_01","lesson":9,"part":2,"paragraph":3,"difficulty":"Basic","skill":"Chronology","en":["During what period did many more Latin and Greek words enter English?",["The Renaissance in the sixteenth century.","The American Civil War.","The early twenty-first century.","The Norman conquest in 1066."]],"ja":["ラテン語とギリシャ語由来の単語が多数英語に入ったのはいつですか。",["16世紀のルネサンス期","アメリカ南北戦争期","21世紀初頭","1066年のノルマン征服期"]],"correct":0,"evidence":"In the 16th century, during the Renaissance, many more words came into English.","explanation":"16世紀のルネサンス期が示されている。"},{"id":"NEW_L09_P2_p3_02","lesson":9,"part":2,"paragraph":3,"difficulty":"Basic","skill":"Detail","en":["Which two languages supplied many of the new words described here?",["Japanese and Korean.","Latin and Greek.","German and Chinese.","Italian and Spanish only."]],"ja":["ここで紹介される新語の多くは、どの２言語から来ましたか。",["日本語と韓国語","ラテン語とギリシャ語","ドイツ語と中国語","イタリア語とスペイン語だけ"]],"correct":1,"evidence":"Most of these were from Latin and Greek.","explanation":"主な語源としてラテン語とギリシャ語が示される。"},{"id":"NEW_L09_P2_p3_03","lesson":9,"part":2,"paragraph":3,"difficulty":"Standard","skill":"Classification","en":["Which examples are linked to science and technology?",["Manga and sushi.","Beef and pork.","Species and temperature.","Brunch and cellphone."]],"ja":["科学・技術に関係する例として示される語はどれですか。",["mangaとsushi","beefとpork","speciesとtemperature","brunchとcellphone"]],"correct":2,"evidence":"These were words concerned with science and technology such as species and temperature.","explanation":"科学技術関連の例として species と temperature がある。"},{"id":"NEW_L09_P2_p3_04","lesson":9,"part":2,"paragraph":3,"difficulty":"Standard","skill":"Classification","en":["Which examples are linked to art and education?",["Radar and scuba.","Deli and mike.","Google and nylon.","Comedy and ethics."]],"ja":["芸術・教育に関係する例として示される語はどれですか。",["radarとscuba","deliとmike","googleとnylon","comedyとethics"]],"correct":3,"evidence":"As art and education developed, so did the English vocabulary for these: Comedy and ethics are two examples of these words.","explanation":"芸術・教育に関する例が comedy と ethics。"},{"id":"NEW_L09_P2_p3_05","lesson":9,"part":2,"paragraph":3,"difficulty":"Challenge","skill":"Cause/Effect","en":["What development accompanied a richer vocabulary for art and education?",["The end of all cultural exchange.","The creation of the Internet.","The disappearance of schools.","The development of art and education themselves."]],"ja":["芸術と教育の語彙の充実に伴って、何が発展しましたか。",["あらゆる文化交流の終わり","インターネットの誕生","学校の消滅","芸術と教育そのもの"]],"correct":3,"evidence":"As art and education developed, so did the English vocabulary for these: Comedy and ethics are two examples of these words.","explanation":"芸術と教育の発展に伴い、関連語彙も増えた。"},{"id":"NEW_L09_P2_p3_06","lesson":9,"part":2,"paragraph":3,"difficulty":"Challenge","skill":"Main Idea","en":["How did the Renaissance affect English in this account?",["It caused English to stop accepting foreign words.","It introduced many Latin and Greek terms into specialized fields.","It replaced all English words with German words.","It was mainly about the invention of cellphones."]],"ja":["本文によると、ルネサンスは英語にどのような影響を与えましたか。",["英語が外国語を受け入れなくなった","専門分野にラテン語・ギリシャ語由来の語を多数取り入れた","すべての英語の単語をドイツ語に置き換えた","主に携帯電話の発明に関係していた"]],"correct":1,"evidence":"In the 16th century, during the Renaissance, many more words came into English.","explanation":"ルネサンス期の知的発展と語彙流入の関係が中心。"},{"id":"NEW_L09_P2_p4_01","lesson":9,"part":2,"paragraph":4,"difficulty":"Basic","skill":"Definition","en":["What is \"clipping\" as described in the passage?",["Taking a word directly from another language.","Inventing a new material name.","Combining the first letters of several words.","Shortening an existing word."]],"ja":["本文で説明される「clipping（短縮）」とは何ですか。",["他言語から単語をそのまま取り入れること","新しい素材の名前を発明すること","複数の単語の頭文字を組み合わせること","すでにある１つの単語を短くすること"]],"correct":3,"evidence":"Clipping means to shorten a word that already exists.","explanation":"既存の単語を短くする方法がクリッピング。"},{"id":"NEW_L09_P2_p4_02","lesson":9,"part":2,"paragraph":4,"difficulty":"Basic","skill":"Example","en":["What is the longer form of \"deli\"?",["Delight.","Delicate.","Delicatessen.","Delivery."]],"ja":["「deli」の元になった長い単語はどれですか。",["delight（喜び）","delicate（繊細な）","delicatessen（惣菜店）","delivery（配達）"]],"correct":2,"evidence":"This popular word deli is clipped from a longer word, delicatessen.","explanation":"deli の元の単語は delicatessen。"},{"id":"NEW_L09_P2_p4_03","lesson":9,"part":2,"paragraph":4,"difficulty":"Standard","skill":"Example","en":["Which longer word is shortened to \"mike\" in this text?",["Microbiology.","Microscope.","Microwave.","Microphone."]],"ja":["本文では「mike」はどの長い単語を短縮したものですか。",["microbiology（微生物学）","microscope（顕微鏡）","microwave（電子レンジ）","microphone（マイク）"]],"correct":3,"evidence":"When you give a speech, you might use a mike, not a microphone.","explanation":"mike は microphone を短くした形。"},{"id":"NEW_L09_P2_p4_04","lesson":9,"part":2,"paragraph":4,"difficulty":"Standard","skill":"Example","en":["Which word is the longer form of \"exam\"?",["Examiner.","Examinee.","Example.","Examination."]],"ja":["「exam」の元の長い単語はどれですか。",["examiner（試験官）","examinee（受験者）","example（例）","examination（試験）"]],"correct":3,"evidence":"You might have an exam next week, which is short for examination.","explanation":"exam は examination の短縮形。"},{"id":"NEW_L09_P2_p4_05","lesson":9,"part":2,"paragraph":4,"difficulty":"Challenge","skill":"Example","en":["What is \"ad\" short for in the passage?",["Adventure.","Administration.","Advertisement.","Addition."]],"ja":["本文で「ad」は何の短縮形ですか。",["adventure（冒険）","administration（管理・行政）","advertisement（広告）","addition（追加）"]],"correct":2,"evidence":"\"Have you seen the ad for the new smartphone?\" In an informal conversation like this, native speakers would probably not use the longer word advertisement.","explanation":"ad は advertisement の省略形。"},{"id":"NEW_L09_P2_p4_06","lesson":9,"part":2,"paragraph":4,"difficulty":"Challenge","skill":"Register","en":["In what kind of conversation are shortened words especially natural here?",["A scientific formula only.","A formal legal statement only.","Informal conversation.","A medieval religious ceremony."]],"ja":["本文では短縮語はどのような会話で特に自然に使われますか。",["科学の公式だけ","正式な法律文だけ","くだけた日常会話","中世の宗教儀式"]],"correct":2,"evidence":"\"Have you seen the ad for the new smartphone?\" In an informal conversation like this, native speakers would probably not use the longer word advertisement.","explanation":"会話的・くだけた場面で短縮語がよく使われると示される。"},{"id":"NEW_L09_P3_p5_01","lesson":9,"part":3,"paragraph":5,"difficulty":"Basic","skill":"Definition","en":["How is an acronym usually formed according to the text?",["By taking the first letters of a set of words.","By combining parts of just two words.","By translating a word from Italian.","By shortening a single word at its end."]],"ja":["本文によると、頭字語（acronym）は通常どのように作られますか。",["複数の単語の頭文字を取って作る","２つの単語の一部だけを組み合わせる","イタリア語を翻訳する","１つの単語の末尾を短くする"]],"correct":0,"evidence":"Usually the first letter is taken from each word in the set, and that forms a new word.","explanation":"一連の語の頭文字を取って新しい語を作る。"},{"id":"NEW_L09_P3_p5_02","lesson":9,"part":3,"paragraph":5,"difficulty":"Basic","skill":"Example","en":["What does \"scuba\" stand for in the passage?",["Self-Contained Underwater Breathing Apparatus.","Small Camera Used By Astronauts.","Scientific Computer Underwater Basic Analysis.","South Canadian Underwater Boat Association."]],"ja":["本文で「scuba」の元となる語句はどれですか。",["自給式水中呼吸装置（Self-Contained Underwater Breathing Apparatus）","宇宙飛行士が使う小型カメラ","科学的な水中コンピューター基本分析","南カナダ水中ボート協会"]],"correct":0,"evidence":"Few remember that scuba comes from a much longer set of words: Self-Contained Underwater Breathing Apparatus.","explanation":"scuba の正式な展開形は本文で明記されている。"},{"id":"NEW_L09_P3_p5_03","lesson":9,"part":3,"paragraph":5,"difficulty":"Standard","skill":"Example","en":["What is the expansion of \"radar\"?",["Rapid Data And Research.","Remote Audio Digital Access Route.","Railroad Detection And Rescue.","Radio Detection And Ranging."]],"ja":["「radar」の元となる語句はどれですか。",["迅速なデータと研究","遠隔音声デジタルアクセス経路","鉄道の探知と救助","電波による探知と測距（Radio Detection And Ranging）"]],"correct":3,"evidence":"It means RAdio Detection And Ranging.","explanation":"radar は Radio Detection And Ranging の頭字語。"},{"id":"NEW_L09_P3_p5_04","lesson":9,"part":3,"paragraph":5,"difficulty":"Standard","skill":"Example","en":["What is the expansion of \"laser\"?",["Light Amplification by Stimulated Emission of Radiation.","Light And Sound Energy Reflection.","Long Air Signal Electronic Radar.","Linguistic Analysis of Spoken English Rules."]],"ja":["「laser」の元となる語句はどれですか。",["放射の誘導放出による光増幅（Light Amplification by Stimulated Emission of Radiation）","光と音のエネルギー反射","長距離空中信号電子レーダー","話し言葉の英語規則の言語分析"]],"correct":0,"evidence":"Also, not many native speakers recall that laser is an acronym meaning Light Amplification by Stimulated Emission of Radiation.","explanation":"laser の正式名称が本文に示されている。"},{"id":"NEW_L09_P3_p5_05","lesson":9,"part":3,"paragraph":5,"difficulty":"Challenge","skill":"Inference","en":["What do scuba, radar, and laser have in common?",["They are all examples of clipping.","They are formed from initial letters of longer expressions.","They are names of new foods.","They are all borrowed from Japanese."]],"ja":["scuba・radar・laserの共通点は何ですか。",["すべて短縮の例である","長い表現の頭文字から作られた","すべて新しい食べ物の名前である","すべて日本語から借用された"]],"correct":1,"evidence":"An acronym is made from a set of existing words.","explanation":"いずれも長い語句の頭文字を用いた略語である。"},{"id":"NEW_L09_P3_p5_06","lesson":9,"part":3,"paragraph":5,"difficulty":"Challenge","skill":"Contrast","en":["Which statement correctly distinguishes acronyms from clipping?",["Acronyms always come from Italian; clipping always comes from Greek.","Acronyms name animals; clipping names inventions only.","Acronyms use letters from several words; clipping shortens one word.","Acronyms are never used in technology."]],"ja":["頭字語と短縮の違いを正しく説明したものはどれですか。",["頭字語は必ずイタリア語から、短縮は必ずギリシャ語から来る","頭字語は動物名、短縮は発明品の名前だけに使われる","頭字語は複数の語の文字を使い、短縮は１つの語を短くする","頭字語は技術分野では決して使われない"]],"correct":2,"evidence":"Usually the first letter is taken from each word in the set, and that forms a new word.","explanation":"頭字語と単一語の短縮は作り方が異なる。"},{"id":"NEW_L09_P3_p6_01","lesson":9,"part":3,"paragraph":6,"difficulty":"Basic","skill":"Definition","en":["What does blending mean in paragraph 6?",["Putting parts or words together to form another word.","Borrowing words from foreign languages unchanged.","Taking the first letter of each word in a long phrase.","Giving an animal a computer-related meaning."]],"ja":["第６段落で「blending（混成）」とは何を意味しますか。",["既存の語や語の一部を組み合わせて別の語を作ること","外国語の単語をそのまま借用すること","長い句の各単語の頭文字を取ること","動物の名前にコンピューター関連の意味を与えること"]],"correct":0,"evidence":"Other new words are added to English when existing words are put together, or blended.","explanation":"既存の語を組み合わせて新語を作ること。"},{"id":"NEW_L09_P3_p6_02","lesson":9,"part":3,"paragraph":6,"difficulty":"Basic","skill":"Example","en":["Which two words are combined to make \"brunch\"?",["Break and bunch.","Bread and crunch.","Breakfast and dinner.","Breakfast and lunch."]],"ja":["「brunch」はどの２語を組み合わせたものですか。",["break（休憩）とbunch（束）","bread（パン）とcrunch（かむ音）","breakfast（朝食）とdinner（夕食）","breakfast（朝食）とlunch（昼食）"]],"correct":3,"evidence":"Breakfast and lunch are put together to form brunch, for example.","explanation":"brunch の元になるのは breakfast と lunch。"},{"id":"NEW_L09_P3_p6_03","lesson":9,"part":3,"paragraph":6,"difficulty":"Standard","skill":"Example","en":["Which pair produces the word \"cellphone\" in the passage?",["Telephone and microphone.","Cellular and telephone.","Cell and photograph.","Cellular and phonics."]],"ja":["本文では「cellphone」はどの２語を組み合わせたものですか。",["telephoneとmicrophone","cellularとtelephone","cellとphotograph","cellularとphonics"]],"correct":1,"evidence":"Cellular and telephone are combined to make the word cellphone.","explanation":"本文では cellular と telephone の組合せと説明する。"},{"id":"NEW_L09_P3_p6_04","lesson":9,"part":3,"paragraph":6,"difficulty":"Standard","skill":"Classification","en":["Which word is an example of blending rather than an acronym in this passage?",["Laser.","Scuba.","Brunch.","Radar."]],"ja":["この本文で頭字語ではなく混成語の例はどれですか。",["laser","scuba","brunch","radar"]],"correct":2,"evidence":"Breakfast and lunch are put together to form brunch, for example.","explanation":"brunch が混成語の具体例である。"},{"id":"NEW_L09_P3_p6_05","lesson":9,"part":3,"paragraph":6,"difficulty":"Challenge","skill":"Contrast","en":["How does blending differ from forming an acronym?",["There is no difference in the passage.","Blending shortens only one word; acronyms add an ending.","Blending combines word material; an acronym normally uses initial letters.","Blending always begins in Latin; acronyms come from Japanese."]],"ja":["混成語を作る方法は、頭字語の作り方とどう違いますか。",["本文では違いがない","混成は１語だけを短くし、頭字語は語尾を加える","混成は単語の一部などを組み合わせ、頭字語は通常は頭文字を使う","混成語は必ずラテン語、頭字語は日本語から来る"]],"correct":2,"evidence":"Other new words are added to English when existing words are put together, or blended.","explanation":"語を組み合わせる方法と頭文字を使う方法を区別する。"},{"id":"NEW_L09_P3_p6_06","lesson":9,"part":3,"paragraph":6,"difficulty":"Challenge","skill":"Main Idea","en":["What is the main purpose of the brunch and cellphone examples?",["To explain how French conquered England.","To illustrate new words formed by combining existing words.","To list words borrowed from Italy.","To show that English has stopped evolving."]],"ja":["brunchとcellphoneを例に出した主な目的は何ですか。",["フランス人がイングランドを征服した経緯を説明するため","既存の単語を組み合わせて新語ができることを示すため","イタリアから借用された語を列挙するため","英語の変化が止まったことを示すため"]],"correct":1,"evidence":"Other new words are added to English when existing words are put together, or blended.","explanation":"混成語による新語形成を説明するための例。"},{"id":"NEW_L09_P4_p7_01","lesson":9,"part":4,"paragraph":7,"difficulty":"Basic","skill":"Classification","en":["How does the passage classify the word \"google\"?",["Borrowing from Italian.","An acronym from Latin words.","Clipping from a longer word.","Coinage related to Internet technology."]],"ja":["本文では「google」という語をどのように分類していますか。",["イタリア語からの借用語","ラテン語の単語を基にした頭字語","長い単語の短縮形","インターネット技術に関係する新造語"]],"correct":3,"evidence":"The word google is a coinage based on the modern technology of the Internet.","explanation":"google は技術に基づく新造語の例として説明される。"},{"id":"NEW_L09_P4_p7_02","lesson":9,"part":4,"paragraph":7,"difficulty":"Basic","skill":"Classification","en":["Which word is given as another example of coinage?",["Exam.","Nylon.","Scuba.","Piano."]],"ja":["新造語の別の例として示されているのはどれですか。",["exam（試験）","nylon（ナイロン）","scuba（スキューバ）","piano（ピアノ）"]],"correct":1,"evidence":"Another example of coinage is nylon.","explanation":"nylon も新造語として示される。"},{"id":"NEW_L09_P4_p7_03","lesson":9,"part":4,"paragraph":7,"difficulty":"Standard","skill":"Detail","en":["Who is said to have invented the material nylon?",["A Canadian prime minister.","An American scientist.","A Norman ruler.","Queen Victoria."]],"ja":["ナイロンという素材を発明したのは誰だと述べられていますか。",["カナダの首相","アメリカ人科学者","ノルマン人の統治者","ビクトリア女王"]],"correct":1,"evidence":"The name was created when the material was invented by an American scientist in the first half of the 20th century.","explanation":"ナイロンという素材を発明した人物はアメリカの科学者。"},{"id":"NEW_L09_P4_p7_04","lesson":9,"part":4,"paragraph":7,"difficulty":"Standard","skill":"Chronology","en":["When was nylon invented according to the passage?",["After the year 2011.","In the sixteenth century.","Around the eleventh century.","In the first half of the twentieth century."]],"ja":["本文によると、ナイロンが発明されたのはいつですか。",["2011年以降","16世紀","11世紀ごろ","20世紀前半"]],"correct":3,"evidence":"The name was created when the material was invented by an American scientist in the first half of the 20th century.","explanation":"20世紀前半の発明と記述される。"},{"id":"NEW_L09_P4_p7_05","lesson":9,"part":4,"paragraph":7,"difficulty":"Challenge","skill":"Meaning Change","en":["What additional meaning did \"mouse\" gain with computers?",["A foreign word for a piano.","An abbreviation of microphone.","A device for moving the cursor on a screen.","A method of making cloth."]],"ja":["コンピューターに関して「mouse」に追加された意味は何ですか。",["ピアノを表す外国語","microphoneの短縮形","画面のカーソルを動かすための装置","布地を作る方法"]],"correct":2,"evidence":"For example, a mouse used to be just an animal; now it is a device that we use with computers to move the cursor on a computer screen.","explanation":"mouse は動物だけでなくカーソル操作機器の意味を得た。"},{"id":"NEW_L09_P4_p7_06","lesson":9,"part":4,"paragraph":7,"difficulty":"Challenge","skill":"Contrast","en":["What two different ways technology changes vocabulary are illustrated here?",["Only clipping existing words and borrowing Italian terms.","Creating new terms and giving old words new meanings.","Only translating songs and shortening numbers.","Replacing all animal names with numbers."]],"ja":["ここでは技術によって語彙が変化するどの２つの方法が示されていますか。",["既存語の短縮とイタリア語の借用だけ","新しい語を作ることと、既存語に新しい意味を与えること","歌の翻訳と数の短縮だけ","すべての動物名を数字に置き換えること"]],"correct":1,"evidence":"Technology also brings new meanings to existing words.","explanation":"新造語を生むことと既存語の意味を広げることの両方がある。"},{"id":"NEW_L09_P4_p8_01","lesson":9,"part":4,"paragraph":8,"difficulty":"Basic","skill":"Definition","en":["What does \"borrowing\" refer to in this paragraph?",["Old words being used for computer hardware.","Words entering English from other languages.","Words being shortened in informal speech.","Words formed from the first letters of a phrase."]],"ja":["この段落で「borrowing（借用）」とは何を指しますか。",["既存語がコンピューター機器を表すようになること","他の言語から英語に語が入ってくること","くだけた会話で語が短くなること","句の頭文字から語が作られること"]],"correct":1,"evidence":"Many new words entered English this way.","explanation":"他言語から語を取り入れる現象が borrowing。"},{"id":"NEW_L09_P4_p8_02","lesson":9,"part":4,"paragraph":8,"difficulty":"Basic","skill":"Origin","en":["From which language did \"piano\" enter English?",["Japanese.","Greek.","German.","Italian."]],"ja":["「piano」はどの言語から英語に入りましたか。",["日本語","ギリシャ語","ドイツ語","イタリア語"]],"correct":3,"evidence":"For example, the word piano came into English from Italian long ago, as did many words for music.","explanation":"piano の起源としてイタリア語が挙げられる。"},{"id":"NEW_L09_P4_p8_03","lesson":9,"part":4,"paragraph":8,"difficulty":"Standard","skill":"Detail","en":["What other types of words came from Italian according to the text?",["All terms for computer mice.","Every word used in cooking.","All modern Internet terms.","Many words connected with music."]],"ja":["本文によると、ほかにどのような語がイタリア語から来ましたか。",["コンピューターマウスに関するすべての語","料理で使うすべての語","現代のインターネット用語すべて","音楽に関係する多くの語"]],"correct":3,"evidence":"For example, the word piano came into English from Italian long ago, as did many words for music.","explanation":"音楽に関する多くの言葉もイタリア語から入った。"},{"id":"NEW_L09_P4_p8_04","lesson":9,"part":4,"paragraph":8,"difficulty":"Standard","skill":"Origin","en":["Which language is said to be the source of \"manga,\" \"karaoke,\" and \"sushi\"?",["Japanese.","German.","French.","Latin."]],"ja":["「manga」「karaoke」「sushi」は、どの言語から来たと述べられていますか。",["日本語","ドイツ語","フランス語","ラテン語"]],"correct":0,"evidence":"Manga, karaoke, and sushi are all new words that came into English recently thanks to Japanese.","explanation":"これらは日本語由来の例として挙げられる。"},{"id":"NEW_L09_P4_p8_05","lesson":9,"part":4,"paragraph":8,"difficulty":"Challenge","skill":"Contrast","en":["How does the paragraph compare borrowing long ago and today?",["Borrowing happened only before the Renaissance.","Words entered English from other languages in both periods.","English once borrowed from Japanese but never from Italian.","Borrowing started only after the Internet appeared."]],"ja":["この段落は昔と今の借用をどのように比較していますか。",["借用はルネサンス以前にしか起きなかった","昔も今も、他の言語から英語に語が入ってきた","昔の英語は日本語から借りたがイタリア語からは借りなかった","借用はインターネット登場後に初めて始まった"]],"correct":1,"evidence":"Today, words still come into English from other languages.","explanation":"昔も今も借用が続いているという対比である。"},{"id":"NEW_L09_P4_p8_06","lesson":9,"part":4,"paragraph":8,"difficulty":"Challenge","skill":"Main Idea","en":["Which statement best summarizes paragraph 8?",["Technology has prevented languages from mixing.","Only English can create acronyms.","Clipping explains all modern Japanese loanwords.","English expands by accepting words from other languages."]],"ja":["第８段落の要約として最も適切なものはどれですか。",["技術のせいで言語同士が混じらなくなった","頭字語を作れるのは英語だけだ","現代の日本語由来の借用語はすべて短縮で説明できる","英語は他の言語から語を受け入れることで広がっている"]],"correct":3,"evidence":"Finally, let's look at borrowing.","explanation":"段落全体は借用語による語彙増加を説明している。"},{"id":"NEW_L09_P4_p9_01","lesson":9,"part":4,"paragraph":9,"difficulty":"Basic","skill":"Recall","en":["Which list contains all five word-formation processes named in the conclusion?",["Clipping, acronyms, blending, coinage, and borrowing.","Coinage, painting, geography, science, and sports.","Borrowing, memorizing, speaking, listening, and drawing.","Clipping, translation, singing, reading, and writing."]],"ja":["結論に登場する５つの語形成過程をすべて含むものはどれですか。",["短縮・頭字語・混成・新造・借用","新造・絵画・地理・科学・スポーツ","借用・暗記・発話・聴取・描画","短縮・翻訳・歌唱・読書・作文"]],"correct":0,"evidence":"Clipping, acronyms, blending, coinage, borrowing―these happen in every language.","explanation":"最後の段落は五つの語形成方法を総括する。"},{"id":"NEW_L09_P4_p9_02","lesson":9,"part":4,"paragraph":9,"difficulty":"Basic","skill":"Generalization","en":["According to the paragraph, in how many languages do these changes occur?",["In every language.","Only in written languages.","Only in European languages.","Only in English."]],"ja":["この段落によると、こうした変化は何種類の言語で起こりますか。",["すべての言語","書き言葉を持つ言語だけ","ヨーロッパの言語だけ","英語だけ"]],"correct":0,"evidence":"Clipping, acronyms, blending, coinage, borrowing―these happen in every language.","explanation":"同様の変化はあらゆる言語に起こるとある。"},{"id":"NEW_L09_P4_p9_03","lesson":9,"part":4,"paragraph":9,"difficulty":"Standard","skill":"Cause/Effect","en":["What causes a language to grow and change according to the author?",["The publication of a single dictionary only.","Changes in people and the world.","The disappearance of all borrowed words.","A rule requiring every word to remain fixed."]],"ja":["筆者によると、言語が成長し変化する原因は何ですか。",["一冊の辞典が出版されることだけ","人々や世界が変化すること","借用語がすべて消えること","すべての単語を固定する規則"]],"correct":1,"evidence":"A language grows and changes as people and the world change.","explanation":"人々や世界の変化に応じて言語も変化する。"},{"id":"NEW_L09_P4_p9_04","lesson":9,"part":4,"paragraph":9,"difficulty":"Standard","skill":"Detail","en":["Why does the author suggest English may change particularly quickly?",["It has no borrowed vocabulary.","It has exactly twenty words.","It is widely used as a global language.","It is spoken only in one small village."]],"ja":["英語は特に速く変化するかもしれないと筆者が考えるのはなぜですか。",["借用語が全くないから","単語がちょうど20個しかないから","世界共通語として広く使われているから","小さな一つの村でしか話されないから"]],"correct":2,"evidence":"Because English is the most commonly used global language, it might be growing and changing faster than other languages.","explanation":"世界的に広く使われることが理由として挙げられる。"},{"id":"NEW_L09_P4_p9_05","lesson":9,"part":4,"paragraph":9,"difficulty":"Challenge","skill":"Inference","en":["Does the final sentence claim with certainty that English changes faster than all others?",["No, it presents this as a possibility.","Yes, it proves this with exact speed measurements.","No, it says English never changes.","Yes, it states that all other languages have stopped."]],"ja":["最後の文は、英語がどの言語よりも速く変化すると断定していますか。",["いいえ、可能性として述べているだけです","はい、正確な速度の測定値で証明しています","いいえ、英語は決して変化しないと述べています","はい、他の言語はすべて変化をやめたと述べています"]],"correct":0,"evidence":"Because English is the most commonly used global language, it might be growing and changing faster than other languages.","explanation":"might が使われ、可能性として述べている。"},{"id":"NEW_L09_P4_p9_06","lesson":9,"part":4,"paragraph":9,"difficulty":"Challenge","skill":"Main Idea","en":["What is the author's overall conclusion about language?",["The growth of English has ended.","A dictionary alone determines all future language changes.","Only ancient languages can develop new words.","Languages continue evolving as society changes."]],"ja":["言語についての筆者の全体的な結論は何ですか。",["英語の成長は終わった","一冊の辞典だけで言語の将来の変化がすべて決まる","古代の言語だけが新語を作れる","社会の変化につれて言語も進化し続ける"]],"correct":3,"evidence":"A language grows and changes as people and the world change.","explanation":"言語の変化は社会や人間の変化と結びつくという結論である。"},{"id":"NEW_L08_P1_p1_07","lesson":8,"part":1,"paragraph":1,"difficulty":"Challenge","skill":"Synthesis","en":["Which country is connected both with the chapel at the end of the route and Harriet's later destination?",["Germany.","Italy.","Canada.","Mexico."]],"ja":["経路の終点にある礼拝堂と、後のハリエットの目的地の両方に関係する国はどれですか。",["ドイツ","イタリア","カナダ","メキシコ"]],"correct":2,"evidence":"In 1999, the Canadian government formally chose a small chapel in St. Catharines as a National Historic Site of Canada.\nThe Fugitive Slave Law of 1850, which prohibited anyone from helping escaping slaves, now made it dangerous for runaways to stop anywhere in the U.S. So Harriet led her followers to Canada, where they would be safe and free.","explanation":"礼拝堂の所在地と逃亡者の安全な到達先はいずれもカナダとつながる。"},{"id":"NEW_L08_P1_p2_07","lesson":8,"part":1,"paragraph":2,"difficulty":"Challenge","skill":"Synthesis","en":["How were escaping people helped both on the route and through songs?",["Stations were schools, while songs gave passengers tickets.","Stations offered shelter, while songs passed on hidden route information.","Stations made maps, while songs were used only for entertainment.","Stations wrote dictionaries, while songs offered legal protection."]],"ja":["逃亡者は、経路上と歌の両方を通じてどのように助けられたのですか。",["停車駅は学校で、歌が乗客に切符を与えた","停車駅が避難場所を提供し、歌が秘密の経路情報を伝えた","停車駅が地図を作り、歌は娯楽だけに使われた","停車駅が辞書を作り、歌が法的保護を与えた"]],"correct":1,"evidence":"There, escaping slaves were hidden, warmed, and fed―in homes, barns, and sometimes churches.\nIt is said that songs known as Negro spirituals contained secret messages.","explanation":"物理的な避難場所と情報伝達の両面で支援があった。"},{"id":"NEW_L08_P2_p3_07","lesson":8,"part":2,"paragraph":3,"difficulty":"Challenge","skill":"Synthesis","en":["Which two forms of guidance are mentioned in Part 2?",["Government newspapers and Internet maps.","Secret messages in songs and the North Star.","Public train schedules and royal medals.","Restaurant menus and printed dictionaries."]],"ja":["Part 2で言及された、道案内になる２つのものはどれですか。",["政府の新聞とインターネット地図","歌に隠されたメッセージと北極星","公の列車時刻表と王室のメダル","レストランのメニューと印刷された辞書"]],"correct":1,"evidence":"It is said that songs known as Negro spirituals contained secret messages.\nShe used the North Star to guide her.","explanation":"歌に隠された合図と、進路の目印となる北極星が登場する。"},{"id":"NEW_L08_P2_p5_07","lesson":8,"part":2,"paragraph":5,"difficulty":"Challenge","skill":"Chronology","en":["Which happened first in Harriet's story?",["She escaped to Philadelphia alone.","A commemorative plaque was unveiled.","She received a silver medal from Queen Victoria.","She returned to Maryland to help relatives."]],"ja":["ハリエットの物語では、次のうち最初に起こったことはどれですか。",["一人でフィラデルフィアへ逃げた","記念の銘板が除幕された","ビクトリア女王から銀メダルを受け取った","親族を助けるためメリーランド州に戻った"]],"correct":0,"evidence":"At last, she got to Philadelphia.\nSome months later, she went back to Maryland and met her family again.","explanation":"一人でフィラデルフィアに着いてから、家族のためにメリーランドへ戻った。"},{"id":"NEW_L08_P2_p5_08","lesson":8,"part":2,"paragraph":5,"difficulty":"Challenge","skill":"Character","en":["What quality is shown both by Harriet's solo escape and her later leadership?",["Reliance on train tickets instead of her own decisions.","A desire to gain money from slaveholders.","Courage and determination despite danger.","A wish to avoid all responsibility for others."]],"ja":["ハリエットの単独での逃亡と、その後の指導力の両方に表れた資質は何ですか。",["自分の判断ではなく列車の切符に頼ること","奴隷所有者から金銭を得たいという願い","危険に直面しても示す勇気と決意","他者への責任をすべて避けたいという願い"]],"correct":2,"evidence":"She kept traveling for freedom at the risk of her life.\nHarriet's reputation as a fearless leader spread fast.","explanation":"一人で危険を冒して進み、その後も恐れを知らない指導者として行動した。"},{"id":"NEW_L08_P3_p6_07","lesson":8,"part":3,"paragraph":6,"difficulty":"Challenge","skill":"Synthesis","en":["Why did the destination of Harriet's rescue efforts eventually extend beyond the United States?",["Her husband was appointed governor of Canada.","All U.S. rivers disappeared.","A law made staying anywhere in the U.S. dangerous for escapees.","The North Star moved to Canada."]],"ja":["ハリエットの救助活動の目的地が、やがてアメリカ国外に広がったのはなぜですか。",["夫がカナダの知事になったから","アメリカのすべての川がなくなったから","法律によってアメリカ国内のどこに留まっても逃亡者に危険が及んだから","北極星がカナダへ移動したから"]],"correct":2,"evidence":"So she led two brothers, a sister, her children, and a dozen more slaves to the North.\nThe Fugitive Slave Law of 1850, which prohibited anyone from helping escaping slaves, now made it dangerous for runaways to stop anywhere in the U.S. So Harriet led her followers to Canada, where they would be safe and free.","explanation":"家族らを北へ導いた後、米国内の危険増大によりカナダへ向かった。"},{"id":"NEW_L08_P3_p8_07","lesson":8,"part":3,"paragraph":8,"difficulty":"Challenge","skill":"Synthesis","en":["How do the slaveholders' rewards and Queen Victoria's medal contrast?",["The rewards praised her humanitarian work, while the medal punished it.","Both were rewards for capturing people escaping slavery.","The rewards sought her capture, while the medal honored her bravery.","Both were payments for opening a restaurant."]],"ja":["奴隷所有者の報奨金とビクトリア女王のメダルは、どう対照的ですか。",["報奨金は人道的活動を称え、メダルはそれを罰した","両方とも奴隷制から逃れる人を捕まえる報酬だった","報奨金は彼女の捕獲が目的で、メダルは勇気を称えた","両方ともレストラン開業の支払いだった"]],"correct":2,"evidence":"Large rewards were offered by slaveholders for catching her.\nFor example, she was awarded a silver medal for bravery by Queen Victoria in 1897.","explanation":"捕獲を目的とする賞金と勇気を称えるメダルは対照的。"},{"id":"NEW_L08_P3_p7_07","lesson":8,"part":3,"paragraph":7,"difficulty":"Challenge","skill":"Chronology","en":["Which came earlier according to the years in the text?",["The plaque unveiled in 2011.","The Emancipation Proclamation of 1863.","The Fugitive Slave Law of 1850.","Queen Victoria's award in 1897."]],"ja":["本文の年号によると、最も早い出来事はどれですか。",["2011年の銘板の除幕","1863年の奴隷解放宣言","1850年の逃亡奴隷法","1897年のビクトリア女王による表彰"]],"correct":2,"evidence":"The Fugitive Slave Law of 1850, which prohibited anyone from helping escaping slaves, now made it dangerous for runaways to stop anywhere in the U.S. So Harriet led her followers to Canada, where they would be safe and free.\nHarriet was over forty years old when Abraham Lincoln signed the Emancipation Proclamation in 1863.","explanation":"1850年の法律が1863年の布告より先にあたる。"},{"id":"NEW_L08_P4_p9_07","lesson":8,"part":4,"paragraph":9,"difficulty":"Challenge","skill":"Chronology","en":["Which sequence correctly follows the four dated events discussed near the end?",["2011 plaque, 1863 proclamation, 1913 death, 1897 medal.","1913 death, 1897 medal, 1863 proclamation, 2011 plaque.","1897 medal, 1863 proclamation, 2011 plaque, 1913 death.","1863 proclamation, 1897 medal, 1913 death, 2011 plaque."]],"ja":["結び近くに登場する４つの日付付きの出来事の正しい順序はどれですか。",["2011年の銘板、1863年の宣言、1913年の死去、1897年のメダル","1913年の死去、1897年のメダル、1863年の宣言、2011年の銘板","1897年のメダル、1863年の宣言、2011年の銘板、1913年の死去","1863年の宣言、1897年のメダル、1913年の死去、2011年の銘板"]],"correct":3,"evidence":"Harriet was over forty years old when Abraham Lincoln signed the Emancipation Proclamation in 1863.\nFor example, she was awarded a silver medal for bravery by Queen Victoria in 1897.","explanation":"1863→1897→1913→2011の順番である。"},{"id":"NEW_L08_P1_p2_08","lesson":8,"part":1,"paragraph":2,"difficulty":"Challenge","skill":"Synthesis","en":["Which theme connects the early escape network and the later proclamation?",["The pursuit of freedom from slavery.","The growth of Internet technology.","The introduction of French food words.","The development of tourism at Niagara Falls."]],"ja":["初期の逃亡ネットワークと、後の奴隷解放宣言をつなぐテーマはどれですか。",["奴隷制からの自由を求めること","インターネット技術の発展","フランス語由来の料理用語の導入","ナイアガラの滝の観光開発"]],"correct":0,"evidence":"The routes to freedom became known as the \"Underground Railroad.\" Secret \"stations\" were set up on the way.\nIt turned the freedom she had desperately worked for into a law.","explanation":"地下鉄道も布告も自由を求める流れでつながる。"},{"id":"NEW_L08_P2_p4_07","lesson":8,"part":2,"paragraph":4,"difficulty":"Challenge","skill":"Synthesis","en":["Which statement correctly describes Harriet's life story in the passage?",["She was born enslaved and was later honored for helping others.","She was born a queen and established a railway company.","She spent her whole life without ever helping others escape.","She was born in Canada after the plaque was unveiled."]],"ja":["本文のハリエットの生涯を正しく説明しているものはどれですか。",["奴隷として生まれ、後に他の人々を助けた功績で称えられた","女王として生まれ、鉄道会社を設立した","生涯を通じて誰の逃亡も助けなかった","記念の銘板が除幕された後にカナダで生まれた"]],"correct":0,"evidence":"She was born into slavery on a plantation in Maryland around 1820.\nHarriet was honored by many people for her humanitarian work.","explanation":"奴隷として生まれた後、多くの人を助け、人道的活動を称えられた。"},{"id":"NEW_L08_P3_p8_08","lesson":8,"part":3,"paragraph":8,"difficulty":"Challenge","skill":"Character","en":["Why is Harriet remembered in the closing part of the text?",["Her bravery and humanitarian efforts brought lasting recognition.","She wrote the Oxford English Dictionary.","She invented a computer device called a mouse.","She founded the Norman dynasty."]],"ja":["本文の結びで、ハリエットが記憶されているのはなぜですか。",["勇気と人道的な努力が後世まで評価されているから","オックスフォード英語辞典を書いたから","「マウス」というコンピューター機器を発明したから","ノルマン朝を創設したから"]],"correct":0,"evidence":"Harriet's reputation as a fearless leader spread fast.\nHarriet was honored by many people for her humanitarian work.","explanation":"勇敢な指導者としての行動と人道的貢献が後世の評価につながる。"},{"id":"NEW_L09_P2_p4_07","lesson":9,"part":2,"paragraph":4,"difficulty":"Challenge","skill":"Classification","en":["Which pair correctly matches word-formation methods to examples?",["Exam = acronym; radar = clipping.","Exam = borrowing; radar = blending.","Exam = coinage; radar = borrowing.","Exam = clipping; radar = acronym."]],"ja":["語形成の方法と例の正しい組み合わせはどれですか。",["exam＝頭字語、radar＝短縮","exam＝借用、radar＝混成","exam＝新造語、radar＝借用","exam＝短縮、radar＝頭字語"]],"correct":3,"evidence":"You might have an exam next week, which is short for examination.\nRadar is another example.","explanation":"examは短縮語、radarは頭字語。"},{"id":"NEW_L09_P3_p5_07","lesson":9,"part":3,"paragraph":5,"difficulty":"Challenge","skill":"Classification","en":["Which pair is made by two different processes?",["Scuba by borrowing and brunch by clipping.","Scuba by blending and brunch by acronym.","Scuba by coinage and brunch by borrowing.","Scuba by acronym and brunch by blending."]],"ja":["異なる２つの語形成方法で作られた語の組み合わせはどれですか。",["scubaは借用、brunchは短縮","scubaは混成、brunchは頭字語","scubaは新造語、brunchは借用","scubaは頭字語、brunchは混成"]],"correct":3,"evidence":"Few remember that scuba comes from a much longer set of words: Self-Contained Underwater Breathing Apparatus.\nBreakfast and lunch are put together to form brunch, for example.","explanation":"scubaは頭字語、brunchは混成語である。"},{"id":"NEW_L09_P2_p4_08","lesson":9,"part":2,"paragraph":4,"difficulty":"Challenge","skill":"Classification","en":["Which of the following is an example of blending, not clipping?",["Ad.","Exam.","Deli.","Cellphone."]],"ja":["短縮ではなく混成の例はどれですか。",["ad","exam","deli","cellphone"]],"correct":3,"evidence":"This popular word deli is clipped from a longer word, delicatessen.\nCellular and telephone are combined to make the word cellphone.","explanation":"cellphoneはcellularとtelephoneを組み合わせた語。"},{"id":"NEW_L09_P4_p7_07","lesson":9,"part":4,"paragraph":7,"difficulty":"Challenge","skill":"Classification","en":["Which process best explains the words \"nylon\" and \"piano\" respectively?",["Clipping and blending.","Coinage and borrowing.","Acronym and clipping.","Borrowing and coinage."]],"ja":["「nylon」と「piano」の語形成方法は、それぞれ何ですか。",["短縮と混成","新造と借用","頭字語と短縮","借用と新造"]],"correct":1,"evidence":"Another example of coinage is nylon.\nFor example, the word piano came into English from Italian long ago, as did many words for music.","explanation":"nylonは新造語、pianoは借用語。"},{"id":"NEW_L09_P4_p7_08","lesson":9,"part":4,"paragraph":7,"difficulty":"Challenge","skill":"Meaning Change","en":["How is the computer meaning of \"mouse\" different from the word \"mike\"?",["Mouse gained a new meaning; mike is a shortened form.","Mouse is an acronym; mike is borrowed from Italian.","Both terms are described as loans from Japan.","Both were invented as names of chemical materials."]],"ja":["コンピューターでの「mouse」の意味は「mike」とどう違いますか。",["mouseには新しい意味が加わり、mikeは短縮形である","mouseは頭字語、mikeはイタリア語からの借用である","両方とも日本語から借りた語として説明される","両方とも化学物質の名前として考案された"]],"correct":0,"evidence":"For example, a mouse used to be just an animal; now it is a device that we use with computers to move the cursor on a computer screen.\nWhen you give a speech, you might use a mike, not a microphone.","explanation":"mouseは意味の拡張、mikeは語形の短縮である。"},{"id":"NEW_L09_P4_p8_07","lesson":9,"part":4,"paragraph":8,"difficulty":"Challenge","skill":"Synthesis","en":["What do \"piano\" and \"beef\" show about the history of English?",["English has absorbed words from other languages at different times.","Both words were made by blending modern computer terms.","English avoided contact with Italian and French completely.","Both were shortened from long single words in New York."]],"ja":["「piano」と「beef」は英語の歴史について何を示していますか。",["英語は異なる時代に他の言語から語を取り入れてきた","両方とも現代のコンピューター用語を混成して作られた","英語はイタリア語やフランス語と全く接触しなかった","両方ともニューヨークで長い単語を短くしたもの"]],"correct":0,"evidence":"For example, the word piano came into English from Italian long ago, as did many words for music.\nFor example, we do not sit down at a restaurant and say, \"I'd like cow, please, and my friend will have pig.\" Instead, we order beef and pork.","explanation":"イタリア語やフランス語の影響が英語に現れている。"},{"id":"NEW_L09_P1_p2_07","lesson":9,"part":1,"paragraph":2,"difficulty":"Challenge","skill":"Chronology","en":["Which influence on English vocabulary is described as earlier?",["The arrival of many French words from 1066.","The rise of Internet-related coinage.","The growth of Latin and Greek vocabulary in the 16th century.","The recent borrowing of sushi from Japanese."]],"ja":["英語の語彙への影響として、最も早く起こったものはどれですか。",["1066年からのフランス語由来の語の流入","インターネットに関係する新造語の登場","16世紀のラテン語・ギリシャ語の語彙の増加","最近の日本語「sushi」の借用"]],"correct":0,"evidence":"But from 1066, lots of French words began coming into English.\nIn the 16th century, during the Renaissance, many more words came into English.","explanation":"1066年は16世紀より前である。"},{"id":"NEW_L09_P2_p3_07","lesson":9,"part":2,"paragraph":3,"difficulty":"Challenge","skill":"Synthesis","en":["Which two developments are linked to English word growth in different periods?",["The Civil War and Harriet Tubman's escape.","Nineteenth-century tourism and geography alone.","Canadian historic sites and railroads.","The Renaissance and modern technology."]],"ja":["異なる時代の英語の語彙増加と関係する２つの発展はどれですか。",["南北戦争とハリエット・タブマンの逃亡","19世紀の観光と地理だけ","カナダの史跡と鉄道","ルネサンスと現代の技術"]],"correct":3,"evidence":"In the 16th century, during the Renaissance, many more words came into English.\nTechnology often offers new words.","explanation":"異なる時代の文化・技術の進展が語彙増加に結びつく。"},{"id":"NEW_L09_P3_p6_07","lesson":9,"part":3,"paragraph":6,"difficulty":"Challenge","skill":"Classification","en":["Which pair correctly matches an example of blending and one of borrowing?",["Brunch and sushi.","Radar and scuba.","Deli and exam.","Sushi and brunch."]],"ja":["混成語と借用語の例がこの順に並んでいるのはどれですか。",["brunchとsushi","radarとscuba","deliとexam","sushiとbrunch"]],"correct":0,"evidence":"Breakfast and lunch are put together to form brunch, for example.\nManga, karaoke, and sushi are all new words that came into English recently thanks to Japanese.","explanation":"brunchは混成語、sushiは日本語からの借用語。"},{"id":"NEW_L09_P3_p5_08","lesson":9,"part":3,"paragraph":5,"difficulty":"Challenge","skill":"Classification","en":["Which pair contains an acronym and a coinage respectively?",["Nylon and laser.","Laser and nylon.","Cellphone and deli.","Piano and sushi."]],"ja":["頭字語と新造語がこの順に並んでいる組み合わせはどれですか。",["nylonとlaser","laserとnylon","cellphoneとdeli","pianoとsushi"]],"correct":1,"evidence":"Also, not many native speakers recall that laser is an acronym meaning Light Amplification by Stimulated Emission of Radiation.\nAnother example of coinage is nylon.","explanation":"laserが頭字語、nylonが新造語である。"},{"id":"NEW_L09_P2_p4_09","lesson":9,"part":2,"paragraph":4,"difficulty":"Challenge","skill":"Classification","en":["Which example of a borrowed word is NOT presented as a clipped word?",["Karaoke.","Ad.","Mike.","Exam."]],"ja":["借用語の例で、短縮語としては紹介されていないものはどれですか。",["karaoke（カラオケ）","ad（広告）","mike（マイク）","exam（試験）"]],"correct":0,"evidence":"You might have an exam next week, which is short for examination.\nManga, karaoke, and sushi are all new words that came into English recently thanks to Japanese.","explanation":"karaokeは日本語からの借用であり、本文のクリッピング例ではない。"},{"id":"NEW_L09_P3_p5_09","lesson":9,"part":3,"paragraph":5,"difficulty":"Challenge","skill":"Contrast","en":["Which statement about acronyms and clipping agrees with the passage?",["An acronym draws on multiple words; clipping shortens an existing word.","Both methods always rely on invented chemical names.","An acronym must be borrowed from Japan; clipping must come from Italy.","Clipping requires the first letters of several words, unlike acronyms."]],"ja":["頭字語と短縮について、本文に合う説明はどれですか。",["頭字語は複数の語を基にし、短縮は既存の１語を短くする","両方とも化学物質の新しい名称だけを基にする","頭字語は必ず日本語から、短縮は必ずイタリア語から借りる","短縮は頭字語と違って複数の語の頭文字を必要とする"]],"correct":0,"evidence":"An acronym is made from a set of existing words.\nClipping means to shorten a word that already exists.","explanation":"複数語の頭文字を使う方法と単一語を短くする方法の違い。"},{"id":"NEW_L09_P4_p9_07","lesson":9,"part":4,"paragraph":9,"difficulty":"Challenge","skill":"Synthesis","en":["How do the beginning and conclusion of the lesson connect?",["Both emphasize that English keeps expanding and changing.","Both say English is the only language that can change.","Both argue dictionaries should contain only twenty entries.","Both claim English vocabulary has completely stopped growing."]],"ja":["このLessonの冒頭と結論は、どのようにつながっていますか。",["英語が拡大・変化し続けていることをともに強調している","変化できる言語は英語だけだと両方とも述べる","辞典は20項目だけにすべきだと両方とも論じる","英語の語彙の増加は完全に止まったと両方とも述べる"]],"correct":0,"evidence":"A language grows and changes as people and the world change.\nNevertheless, English is still growing and adding more words.","explanation":"導入と結論の両方が英語の変化と成長を強調する。"},{"id":"NEW_L09_P4_p9_08","lesson":9,"part":4,"paragraph":9,"difficulty":"Challenge","skill":"Inference","en":["Why would \"sushi\" fit the lesson's overall conclusion?",["It proves all English words originate in the U.S.","It illustrates how contact between people and cultures can change vocabulary.","It shows that borrowed words cannot become English words.","It is an acronym derived from a scientific phrase."]],"ja":["「sushi」はLesson全体の結論にどう当てはまりますか。",["英語のすべての単語がアメリカ発祥だと証明する","人々や文化の接触が語彙を変える例になっている","借用語が英語の単語にはなれないことを示す","科学的な句から作られた頭字語である"]],"correct":1,"evidence":"A language grows and changes as people and the world change.\nManga, karaoke, and sushi are all new words that came into English recently thanks to Japanese.","explanation":"文化と言語の接触が語彙を変えるという結論に合致する。"},{"id":"NEW_L09_P4_p7_09","lesson":9,"part":4,"paragraph":7,"difficulty":"Challenge","skill":"Classification","en":["Which pair best illustrates creating a brand-new term versus combining existing words?",["Google and brunch.","Piano and sushi.","Deli and exam.","Brunch and google."]],"ja":["新しい語の創造と既存語の組み合わせを、この順で最もよく示すものはどれですか。",["googleとbrunch","pianoとsushi","deliとexam","brunchとgoogle"]],"correct":0,"evidence":"The word google is a coinage based on the modern technology of the Internet.\nBreakfast and lunch are put together to form brunch, for example.","explanation":"googleは新造語、brunchは混成語である。"},{"id":"NEW_L09_P4_p8_08","lesson":9,"part":4,"paragraph":8,"difficulty":"Challenge","skill":"Classification","en":["Which pair correctly separates borrowing from acronyms?",["Both are clipping of a single longer word.","Piano is an acronym; scuba is borrowed from Italian.","Both are examples of new meanings for animal names.","Piano is borrowed; scuba is an acronym."]],"ja":["借用と頭字語を正しく区別した組み合わせはどれですか。",["両方とも１つの長い語の短縮形","pianoは頭字語、scubaはイタリア語からの借用語","両方とも動物名に新しい意味を与えた例","pianoは借用語、scubaは頭字語"]],"correct":3,"evidence":"For example, the word piano came into English from Italian long ago, as did many words for music.\nFew remember that scuba comes from a much longer set of words: Self-Contained Underwater Breathing Apparatus.","explanation":"pianoはイタリア語からの借用、scubaは頭字語。"},{"id":"NEW_L10_P1_p1_01","lesson":10,"part":1,"paragraph":1,"difficulty":"Basic","skill":"Detail","en":["Who are dogs in the U.S. said to bark at from inside their houses?",["Their veterinarians.","Other dogs at parks.","Mail carriers.","Their owners at dinner."]],"ja":["アメリカで犬が家の中から吠える相手として挙げられているのは誰ですか。",["犬の獣医","公園にいるほかの犬","郵便配達人","夕食中の飼い主"]],"correct":2,"evidence":"Dogs often bark at mail carriers from inside their houses in the U.S.","explanation":"本文冒頭では、犬が家の中から郵便配達人に向かって吠える例が示されています。"},{"id":"NEW_L10_P1_p1_02","lesson":10,"part":1,"paragraph":1,"difficulty":"Basic","skill":"Detail","en":["What do owners ask their dogs to do?",["Eat their food.","Run outside.","Stop barking.","Follow the mail carrier."]],"ja":["飼い主は犬に何をするように言いますか。",["餌を食べる","外へ走って行く","吠えるのをやめる","郵便配達人について行く"]],"correct":2,"evidence":"Owners tell their dogs to stop barking","explanation":"飼い主は吠えるのをやめるよう指示します。"},{"id":"NEW_L10_P1_p1_03","lesson":10,"part":1,"paragraph":1,"difficulty":"Basic","skill":"Detail","en":["How often do the dogs obey the request to stop barking?",["Seldom.","Usually at once.","Always.","Every time the door opens."]],"ja":["犬が吠えるのをやめるようにという指示に従う頻度はどの程度ですか。",["めったに従わない","たいていすぐ従う","いつも従う","ドアが開くたびに従う"]],"correct":0,"evidence":"but they seldom do.","explanation":"seldom は「めったに〜ない」。飼い主の指示に犬が従うことはまれです。"},{"id":"NEW_L10_P1_p1_04","lesson":10,"part":1,"paragraph":1,"difficulty":"Standard","skill":"LanguageInContext","en":["What does the comparison \"as if the dog were their children\" suggest about the owners?",["They react to their dogs as though they were children.","They complain that children should deliver mail.","They think the dogs are smaller than children.","They believe the dogs can speak like children."]],"ja":["「まるで犬が自分の子どもであるかのように」とは飼い主のどんな態度を表していますか。",["犬を子どものように扱って反応する","子どもが郵便配達をするべきだと文句を言っている","犬は子どもより体が小さいと思っている","犬が子どものように話せると信じている"]],"correct":0,"evidence":"as if the dog were their children","explanation":"as if は「まるで〜であるかのように」。犬を子どもに重ねて考えている飼い主の態度を表します。"},{"id":"NEW_L10_P1_p1_05","lesson":10,"part":1,"paragraph":1,"difficulty":"Basic","skill":"Detail","en":["Which other workers are mentioned as strangers near a home?",["Airline pilots.","Restaurant cooks.","School librarians.","Construction workers."]],"ja":["家の近くにいる見知らぬ人として、他にどんな仕事の人が挙げられていますか。",["航空機のパイロット","レストランの料理人","学校の司書","建設作業員"]],"correct":3,"evidence":"such as construction workers","explanation":"郵便配達人のほか、家のすぐ外の通りで働く建設作業員が例示されています。"},{"id":"NEW_L10_P1_p1_06","lesson":10,"part":1,"paragraph":1,"difficulty":"Standard","skill":"Inference","en":["What do mail carriers and construction workers have in common in these examples?",["They are necessarily the dog’s owners.","They can be unfamiliar people near a dog’s home.","They always enter the house to feed the dog.","They train dogs professionally."]],"ja":["郵便配達人と建設作業員の例に共通する点は何ですか。",["必ずその犬の飼い主である","犬の家の近くにいる、見慣れない人々である","いつも家に入って犬に餌を与える","職業として犬を訓練する"]],"correct":1,"evidence":"The same situation might happen to dogs when strangers, such as construction workers, work in the street just outside of their homes.","explanation":"両者は家の近くに現れる見知らぬ人として挙げられています。犬の吠える対象になり得る点が共通します。"},{"id":"NEW_L10_P1_p1_07","lesson":10,"part":1,"paragraph":1,"difficulty":"Standard","skill":"MainIdea","en":["What everyday problem does the opening paragraph introduce?",["Dogs refuse to eat food their owners give them.","Dogs bark at people outside even when told to stop.","Dogs cannot recognize their family members.","Mail carriers teach dogs to bark on command."]],"ja":["第1段落で提示されている日常の問題は何ですか。",["犬が飼い主の与える餌を食べない","やめるよう言われても、犬が外の人々に吠える","犬が家族を見分けられない","郵便配達人が命令で吠えるよう犬に教える"]],"correct":1,"evidence":"Owners tell their dogs to stop barking, but they seldom do.","explanation":"第1段落は、外の人に吠える犬と、それを止められない飼い主の困りごとを導入しています。"},{"id":"NEW_L10_P1_p2_01","lesson":10,"part":1,"paragraph":2,"difficulty":"Basic","skill":"Detail","en":["What does \"anthropomorphizing\" mean in this passage?",["Giving pets medicine designed for humans.","Treating pets as if they were humans.","Training pets to guard their houses.","Teaching pets to recognize words."]],"ja":["本文中の anthropomorphizing（擬人化）は何を意味しますか。",["人間用の薬をペットに与えること","ペットをまるで人間のように扱うこと","家を守るようペットを訓練すること","ペットに単語を認識させること"]],"correct":1,"evidence":"Dog owners often treat their pets as if they were humans. This is called anthropomorphizing.","explanation":"擬人化は動物を人間のように考えたり扱ったりすることだと説明されています。"},{"id":"NEW_L10_P1_p2_02","lesson":10,"part":1,"paragraph":2,"difficulty":"Basic","skill":"Detail","en":["What should dog owners remember even though dogs are family members?",["Dogs should never meet strangers.","Dogs must always live outside.","Dogs are still animals.","Dogs behave exactly like children."]],"ja":["犬を家族と考える飼い主が覚えておくべきことは何ですか。",["犬は決して見知らぬ人に会ってはいけない","犬はいつも屋外で暮らす必要がある","犬は今も動物である","犬は子どもと全く同じように行動する"]],"correct":2,"evidence":"though dogs are family members, they are still animals","explanation":"犬は家族の一員でも、依然として動物であることを忘れないようにと述べています。"},{"id":"NEW_L10_P1_p2_03","lesson":10,"part":1,"paragraph":2,"difficulty":"Standard","skill":"CauseEffect","en":["According to the author, what may improve an owner’s relationship with a dog?",["Ignoring every sign of the dog’s behavior.","Expecting the dog to behave like a human.","Understanding the reasons behind the dog’s behavior.","Buying the dog more expensive toys."]],"ja":["犬との関係を改善するうえで何が役立つと筆者は考えていますか。",["犬の行動が示す兆候をすべて無視すること","犬が人間のように行動すると期待すること","犬の行動の背景にある理由を理解すること","より高価なおもちゃを買ってあげること"]],"correct":2,"evidence":"Understanding why dogs behave in certain ways may help you get along better with them.","explanation":"犬の行動の理由を理解することが、よりよい関係に役立つと述べています。"},{"id":"NEW_L10_P1_p2_04","lesson":10,"part":1,"paragraph":2,"difficulty":"Standard","skill":"Inference","en":["Which attitude would the author most likely discourage?",["Remembering that dogs belong to a different species.","Assuming a dog thinks and acts exactly as a human does.","Looking for reasons behind a dog’s habits.","Trying to understand natural canine behavior."]],"ja":["筆者が避けるべきだと考えそうな態度はどれですか。",["犬が人間とは異なる種であると覚えておくこと","犬は人間と全く同じように考え、行動すると思い込むこと","犬の習慣の理由を探ること","犬の自然な行動を理解しようとすること"]],"correct":1,"evidence":"However, it is important for owners to remember that though dogs are family members, they are still animals.","explanation":"本文は擬人化への注意を促しています。犬を人間とまったく同じように理解する姿勢は不適切です。"},{"id":"NEW_L10_P1_p2_05","lesson":10,"part":1,"paragraph":2,"difficulty":"Basic","skill":"VocabularyInContext","en":["In this context, \"get along better with\" is closest in meaning to which phrase?",["Become stronger than.","Move farther away from.","Have a better relationship with.","Give more food to."]],"ja":["この文脈で get along better with に最も近い意味はどれですか。",["相手より強くなる","相手からさらに遠ざかる","より良い関係を築く","より多くの餌を与える"]],"correct":2,"evidence":"get along better with them","explanation":"get along with は「〜とうまくやっていく」。この文では犬との関係をよくすることを指します。"},{"id":"NEW_L10_P1_p2_06","lesson":10,"part":1,"paragraph":2,"difficulty":"Advanced","skill":"TextStructure","en":["How does the second paragraph change the focus from the first?",["It introduces detailed instructions for making shampoo.","It changes from dogs to the history of cats.","It explains a mistaken human-centered view of dogs and offers a guiding principle.","It claims the barking problem has no solution."]],"ja":["第2段落は第1段落から話題をどう発展させていますか。",["シャンプーの作り方を詳しく説明する","犬の話からネコの歴史へ話題を移す","犬を人間中心に捉える誤った見方を説明し、基本方針を示す","吠える問題に解決策はないと主張する"]],"correct":2,"evidence":"Dog owners often treat their pets as if they were humans. This is called anthropomorphizing.","explanation":"第1段落の具体的な困りごとから、犬を人間扱いしすぎないという基本的な考え方へ話を進めています。"},{"id":"NEW_L10_P1_p2_07","lesson":10,"part":1,"paragraph":2,"difficulty":"Standard","skill":"Inference","en":["What is the author’s view of dogs being family members?",["It means dogs can understand human motives perfectly.","It proves dogs should make all household decisions.","It is impossible because dogs cannot live with people.","It can be true, but it does not erase their animal nature."]],"ja":["犬が「家族の一員」であることについての筆者の考えはどれですか。",["犬は人間の動機を完全に理解できるという意味だ","犬が家庭のすべての決定をするべきだと証明する","犬は人間と暮らせないので不可能だ","家族の一員と言えても、動物としての性質は消えない"]],"correct":3,"evidence":"though dogs are family members, they are still animals","explanation":"犬が家族の一員だという考えを否定せず、それでも動物としての特性を理解すべきだとしています。"},{"id":"NEW_L10_P1_p3_01","lesson":10,"part":1,"paragraph":3,"difficulty":"Basic","skill":"Detail","en":["What natural instinct do most dogs have?",["To sleep beside open windows.","To avoid every human being.","To hide food in rivers.","To guard their homes from strangers."]],"ja":["多くの犬がもつ生まれつきの本能は何ですか。",["開いた窓のそばで眠る","すべての人間を避ける","川に食べ物を隠す","見知らぬ人から自分の家を守る"]],"correct":3,"evidence":"Most dogs have a natural instinct to guard their homes from strangers.","explanation":"家を見知らぬ人から守る本能があると説明されています。"},{"id":"NEW_L10_P1_p3_02","lesson":10,"part":1,"paragraph":3,"difficulty":"Basic","skill":"Detail","en":["What kinds of people may make dogs bark near their homes?",["Only people wearing uniforms.","Only their own family members.","Only people carrying dog food.","People who pass by, visit, or stay nearby."]],"ja":["家の近くで犬が吠える対象としてどんな人々が挙げられていますか。",["制服を着た人だけ","自分の家族だけ","ドッグフードを持つ人だけ","家の前を通る人、訪ねてくる人、近くにとどまる人"]],"correct":3,"evidence":"people who pass by, visit, or hang around their homes","explanation":"通り過ぎる人、訪問者、家の周辺にいる人が挙げられています。"},{"id":"NEW_L10_P1_p3_03","lesson":10,"part":1,"paragraph":3,"difficulty":"Standard","skill":"CauseEffect","en":["Why might barking make a dog feel satisfied with its behavior?",["The dog believes it has received a prize.","The dog feels it is performing an important role.","The dog thinks it is learning a new language.","The dog expects to be taken for a walk immediately."]],"ja":["吠えることによって犬が満足する可能性があるのはなぜですか。",["賞をもらったと思うから","重要な役割を果たしていると感じるから","新しい言語を学んでいると思うから","すぐに散歩に連れていってもらえると期待するから"]],"correct":1,"evidence":"it probably makes the dog feel that he or she is carrying out an important role","explanation":"吠えることによって自分が重要な役割を果たしていると感じる、と説明されています。"},{"id":"NEW_L10_P1_p3_04","lesson":10,"part":1,"paragraph":3,"difficulty":"Standard","skill":"Contrast","en":["How can an owner and a dog react differently to the same barking?",["Both may be trying to attract other dogs to the house.","The owner may feel useful while the dog feels ashamed.","The owner may be annoyed, while the dog may feel useful.","Both may think the dog is being punished."]],"ja":["犬の吠える行動に対し、飼い主と犬はどう違う反応を示す可能性がありますか。",["両方ともほかの犬を家に呼び寄せようとしている","飼い主は役立つと感じ、犬は恥ずかしく感じる","飼い主は困り、犬は役に立っていると感じるかもしれない","両方とも犬が罰を受けていると思うかもしれない"]],"correct":2,"evidence":"While dogs' barking might bother the owners, it probably makes the dog feel that he or she is carrying out an important role.","explanation":"飼い主には迷惑でも、犬にとっては大切な役割だと感じられる、という対比です。"},{"id":"NEW_L10_P1_p3_05","lesson":10,"part":1,"paragraph":3,"difficulty":"Basic","skill":"VocabularyInContext","en":["What does \"guard\" mean as used in this paragraph?",["Borrow.","Protect.","Forget.","Move."]],"ja":["この段落で guard はどんな意味で使われていますか。",["借りる","守る","忘れる","動く"]],"correct":1,"evidence":"guard their homes from strangers","explanation":"guard はここでは「守る」。見知らぬ人から家を守るという意味です。"},{"id":"NEW_L10_P1_p3_06","lesson":10,"part":1,"paragraph":3,"difficulty":"Advanced","skill":"Inference","en":["Why might repeatedly telling a dog to be quiet fail?",["The dog has forgotten where it lives.","The dog’s urge to protect the home comes from instinct.","The dog has been taught to count strangers.","The dog cannot hear any sound from outside."]],"ja":["繰り返し静かにするよう言っても犬が吠え続ける可能性があるのはなぜですか。",["自分の住む場所を忘れたから","家を守ろうとする衝動が本能に由来するから","犬が見知らぬ人の数を数えるよう教えられているから","外の音がまったく聞こえないから"]],"correct":1,"evidence":"Most dogs have a natural instinct to guard their homes from strangers.","explanation":"吠える行動には家を守ろうとする本能が関わるため、命令だけでは止まらないと推論できます。"},{"id":"NEW_L10_P1_p3_07","lesson":10,"part":1,"paragraph":3,"difficulty":"Standard","skill":"TextStructure","en":["What does the final sentence of this paragraph prepare the reader for?",["Practical ways to reduce barking.","An explanation of how dogs bury food.","A description of the first domesticated dog.","A list of dangerous dog breeds."]],"ja":["この段落の最後の文は次にどんな話題が続くことを示していますか。",["吠えを減らす具体的な方法","犬が食べ物を埋める理由","最初に家畜化された犬の説明","危険な犬種の一覧"]],"correct":0,"evidence":"However, there are some ways to stop dogs from doing this.","explanation":"最後の文は、次に吠える行動を抑える具体的な方法が示されることを予告しています。"},{"id":"NEW_L10_P2_p4_01","lesson":10,"part":2,"paragraph":4,"difficulty":"Basic","skill":"Detail","en":["What is one suggested way to make a dog notice outside noises less?",["Play music.","Open all the windows.","Invite more workers into the yard.","Remove the dog’s food."]],"ja":["犬が外の物音に気づきにくくなる方法として何が提案されていますか。",["音楽をかける","すべての窓を開ける","もっと多くの作業員を庭に招く","犬の餌を取り除く"]],"correct":0,"evidence":"One way is to play music.","explanation":"音楽をかけることが、外の物音に気づきにくくする方法として示されています。"},{"id":"NEW_L10_P2_p4_02","lesson":10,"part":2,"paragraph":4,"difficulty":"Standard","skill":"CauseEffect","en":["Why might music help with barking at construction workers?",["It makes the dog physically unable to bark.","It makes the workers leave the street.","It teaches the dog to recognize every worker.","It reduces how much of the outside noise the dog hears."]],"ja":["音楽が建設作業員への吠えを減らすのに役立つ理由は何ですか。",["犬が身体的に吠えられなくなるから","作業員が通りから立ち去るから","犬がすべての作業員を見分けられるようになるから","外の騒音が犬に聞こえにくくなるから"]],"correct":3,"evidence":"It will reduce the dog's ability to hear. The dog will not notice the noise of the construction workers in the street.","explanation":"音楽によって犬の外の音を聞く能力が低下し、建設作業員の騒音に気づきにくくなります。"},{"id":"NEW_L10_P2_p4_03","lesson":10,"part":2,"paragraph":4,"difficulty":"Basic","skill":"Detail","en":["Where should owners move furniture to prevent dogs from looking outside?",["Next to the windows.","Closer to the front door.","Onto the roof.","Away from windows."]],"ja":["外を見えにくくするため家具はどこへ移すべきですか。",["窓のそばに置く","玄関に近づける","屋根の上に置く","窓から離す"]],"correct":3,"evidence":"Another solution is to move the furniture away from windows.","explanation":"窓から家具を離して置くことが提案されています。"},{"id":"NEW_L10_P2_p4_04","lesson":10,"part":2,"paragraph":4,"difficulty":"Standard","skill":"CauseEffect","en":["How does moving furniture away from windows help?",["It prevents the dog from climbing up to look outside.","It makes the dog’s food safer from insects.","It keeps all strangers from entering the street.","It gives the dog a better view of passersby."]],"ja":["家具を窓から離すことが役立つのはなぜですか。",["犬が家具によじ登って外を見るのを防ぐ","犬の餌を虫から守る","すべての見知らぬ人が通りに入るのを防ぐ","犬から通行人をもっとよく見えるようにする"]],"correct":0,"evidence":"the dog will not be able to climb up on it to see outside","explanation":"窓際の家具に登って外を見ることができなくなるため、吠えるきっかけを減らせます。"},{"id":"NEW_L10_P2_p4_05","lesson":10,"part":2,"paragraph":4,"difficulty":"Standard","skill":"Comparison","en":["What is a shared aim of playing music and moving furniture?",["To limit stimuli that trigger the dog’s barking.","To help dogs communicate with construction workers.","To train owners to leave their dogs outside.","To make dogs sleep during the entire day."]],"ja":["音楽をかけることと家具を動かすことに共通する目的は何ですか。",["犬が吠えるきっかけとなる刺激を減らすこと","建設作業員と犬が意思疎通できるようにすること","飼い主が犬を外に出すよう訓練すること","犬を一日中眠らせること"]],"correct":0,"evidence":"Another solution is to move the furniture away from windows.","explanation":"音を聞きにくくする方法と外を見えにくくする方法のどちらも、吠えるきっかけを減らすことが共通の目的です。"},{"id":"NEW_L10_P2_p4_06","lesson":10,"part":2,"paragraph":4,"difficulty":"Basic","skill":"Detail","en":["Whose noise does the dog become less likely to notice when music is playing?",["Other dogs eating nearby.","Construction workers in the street.","Children playing inside the house.","Its owner giving commands."]],"ja":["音楽が流れることで、犬は誰の騒音に気づきにくくなりますか。",["近くで餌を食べるほかの犬","通りの建設作業員","家の中で遊ぶ子どもたち","指示を出す飼い主"]],"correct":1,"evidence":"the noise of the construction workers in the street","explanation":"外の通りで仕事をする建設作業員の騒音を犬が感じにくくなると説明されています。"},{"id":"NEW_L10_P2_p4_07","lesson":10,"part":2,"paragraph":4,"difficulty":"Advanced","skill":"Application","en":["Which household change best follows the author’s advice?",["Put an extra chair directly beneath the window.","Keep the dog beside the window with the curtains open.","Increase the number of people working outside.","Move a chair the dog uses to watch the street away from the window."]],"ja":["本文の助言を家庭で実践する場合、最も適切な行動はどれですか。",["窓の真下に椅子をもう１脚置く","カーテンを開けて犬を窓際に置く","外で働く人を増やす","犬が通りを見るために使う椅子を窓から離す"]],"correct":3,"evidence":"By doing this, the dog will not be able to climb up on it to see outside.","explanation":"犬が家具に登って外を見ることを防ぐという提案を、椅子の位置変更に応用した選択肢が適切です。"},{"id":"NEW_L10_P2_p5_01","lesson":10,"part":2,"paragraph":5,"difficulty":"Basic","skill":"Detail","en":["What might dogs hide or bury?",["Soap and shampoo.","Shoes and newspapers only.","Keys and phones.","Snacks and bones."]],"ja":["犬は何を隠したり埋めたりすることがありますか。",["石けんとシャンプー","靴と新聞だけ","鍵と電話","おやつと骨"]],"correct":3,"evidence":"Dogs might hide or bury snacks and bones.","explanation":"犬が隠したり埋めたりするものとして、おやつと骨が挙げられています。"},{"id":"NEW_L10_P2_p5_02","lesson":10,"part":2,"paragraph":5,"difficulty":"Basic","skill":"Detail","en":["Why might owners dislike this habit?",["It can leave food around the house or holes in the yard.","It forces the owner to play music all day.","It always causes the dog to lose its sense of smell.","It makes the dog stop eating all food."]],"ja":["犬が食べ物を隠す習性を飼い主が嫌がる理由は何ですか。",["家の中に食べ物が散らかり、庭に穴が開くことがあるから","飼い主が一日中音楽をかける必要があるから","必ず犬の嗅覚が失われるから","犬がすべての食べ物を食べなくなるから"]],"correct":0,"evidence":"most owners probably do not want food lying around their homes or their yards to be full of holes","explanation":"食べ物が家に散らかったり、庭が穴だらけになったりすることが飼い主の困りごとです。"},{"id":"NEW_L10_P2_p5_03","lesson":10,"part":2,"paragraph":5,"difficulty":"Standard","skill":"TextStructure","en":["What new topic does this paragraph introduce?",["Why dogs bark at strangers.","Why dogs avoid taking baths.","How dogs select their favorite music.","Dogs’ habit of hiding or burying food."]],"ja":["この段落で新たに取り上げられる話題は何ですか。",["犬が見知らぬ人に吠える理由","犬が入浴を避ける理由","犬が好きな音楽を選ぶ方法","犬が食べ物を隠したり埋めたりする習性"]],"correct":3,"evidence":"Let's look at another interesting habit that many dogs have.","explanation":"この段落では吠える行動から、食べ物や骨を隠す行動へと話題が移っています。"},{"id":"NEW_L10_P2_p5_04","lesson":10,"part":2,"paragraph":5,"difficulty":"Basic","skill":"VocabularyInContext","en":["In the phrase \"yards to be full of holes,\" what is a \"yard\"?",["An outdoor area beside a house.","A kind of dog snack.","An indoor place to keep books.","A musical instrument."]],"ja":["yards to be full of holes の yard は何を指しますか。",["家のそばの屋外スペース（庭）","犬のおやつの一種","本をしまう屋内の場所","楽器"]],"correct":0,"evidence":"their yards to be full of holes","explanation":"yard はここでは家の庭のこと。犬が地面に穴を掘る場面です。"},{"id":"NEW_L10_P2_p5_05","lesson":10,"part":2,"paragraph":5,"difficulty":"Standard","skill":"Inference","en":["What can reasonably be inferred from the owners’ complaints?",["Dogs do not have any interest in food.","Dogs always hide food because they are starving.","Every owner wants more holes in the yard.","A normal dog behavior can create an unwanted mess for people."]],"ja":["飼い主の不満から何が推論できますか。",["犬は食べ物に全く興味がない","犬は必ず飢えているため食べ物を隠す","すべての飼い主は庭にもっと穴を望んでいる","犬にとって自然な行動が人間にとっては迷惑になることがある"]],"correct":3,"evidence":"most owners probably do not want food lying around their homes","explanation":"犬にとって自然な習慣でも、人間の生活環境では困りごとになると推論できます。"},{"id":"NEW_L10_P2_p5_06","lesson":10,"part":2,"paragraph":5,"difficulty":"Standard","skill":"TextStructure","en":["What does the question at the end of the paragraph encourage readers to consider?",["Whether the habit can be discouraged.","Whether owners should throw away every piece of furniture.","Whether construction workers should move away.","Whether dogs should learn to deliver mail."]],"ja":["段落の最後の疑問文は読者に何を考えさせていますか。",["その習性をやめさせられるかどうか","飼い主がすべての家具を捨てるべきかどうか","建設作業員が立ち去るべきかどうか","犬に郵便配達を教えるべきかどうか"]],"correct":0,"evidence":"Can dogs be persuaded not to do these things?","explanation":"最後の疑問文は、犬がこうした行動をしないようにできるかという次の説明につながります。"},{"id":"NEW_L10_P2_p5_07","lesson":10,"part":2,"paragraph":5,"difficulty":"Advanced","skill":"Comparison","en":["How is the food-hiding issue similar to the barking issue described earlier?",["Both involve dog habits that people may find troublesome.","Both occur only when dogs are outdoors.","Both are solved by moving the dog to a different country.","Both are explained as attempts to get clean after a bath."]],"ja":["食べ物を隠す問題と前半の吠える問題は、どの点で似ていますか。",["どちらも人間が困ることのある犬の習性に関係している","どちらも犬が屋外にいるときだけ起こる","どちらも犬を別の国に移せば解決する","どちらも入浴後に体をきれいにしようとする行動である"]],"correct":0,"evidence":"most owners probably do not want food lying around their homes or their yards to be full of holes","explanation":"吠えることも食べ物を隠すことも、犬の行動が人にとって問題になる例として共通しています。"},{"id":"NEW_L10_P2_p6_01","lesson":10,"part":2,"paragraph":6,"difficulty":"Basic","skill":"Detail","en":["How do people generally feel about eating snacks that have been buried?",["They would not like it.","They would only eat them in summer.","They would usually prefer it.","They always consider it safer."]],"ja":["地面に埋められていたおやつを食べることについて、人は一般にどう感じますか。",["食べたいと思わない","夏にしか食べない","たいていその方が好きだ","いつもその方が安全だと考える"]],"correct":0,"evidence":"People would not like to eat snacks that have been in the ground","explanation":"本文は、人は地面にあったおやつを好まないが犬は気にしない、と比較しています。"},{"id":"NEW_L10_P2_p6_02","lesson":10,"part":2,"paragraph":6,"difficulty":"Basic","skill":"Detail","en":["How do dogs feel about eating snacks that have been in the ground?",["They become unable to smell food.","They would not mind.","They always refuse.","They only eat them if people wash them first."]],"ja":["地面にあったおやつを食べることについて、犬はどう感じますか。",["食べ物の匂いが分からなくなる","気にしない","必ず拒否する","人間が先に洗った場合にだけ食べる"]],"correct":1,"evidence":"but dogs would not mind doing this.","explanation":"犬は地面にあった食べ物を食べることを気にしないと説明されています。"},{"id":"NEW_L10_P2_p6_03","lesson":10,"part":2,"paragraph":6,"difficulty":"Standard","skill":"CauseEffect","en":["Why do dogs bury food, according to the passage?",["To protect it from threats such as insects and heat.","To keep their food close to windows.","To show visitors where they should sit.","To make the food easier for people to find."]],"ja":["本文によると、犬が食べ物を埋める理由は何ですか。",["虫や暑さなどの危険から食べ物を守るため","食べ物を窓のそばに置くため","訪問者が座る位置を示すため","人間が簡単に見つけられるようにするため"]],"correct":0,"evidence":"Food buried in the ground is safe from other animals, flying insects, and the hot sun.","explanation":"埋めた食べ物は他の動物、飛ぶ虫、暑い日差しから守られると書かれています。"},{"id":"NEW_L10_P2_p6_04","lesson":10,"part":2,"paragraph":6,"difficulty":"Basic","skill":"Detail","en":["Which of these is NOT listed as something buried food is protected from?",["Flying insects.","Other animals.","Loud music.","The hot sun."]],"ja":["埋めた食べ物を守る対象として、本文に挙げられていないものはどれですか。",["飛び回る虫","ほかの動物","大きな音の音楽","暑い日差し"]],"correct":2,"evidence":"other animals, flying insects, and the hot sun","explanation":"他の動物・飛ぶ虫・暑い日差しは挙げられていますが、音楽は含まれていません。"},{"id":"NEW_L10_P2_p6_05","lesson":10,"part":2,"paragraph":6,"difficulty":"Standard","skill":"TimeReference","en":["When did dogs learn that burying food was an effective way to protect it?",["After people invented dry shampoo.","When televisions became popular.","Long ago.","Only in recent years."]],"ja":["犬は食べ物を埋める方法が有効だといつ知ったとされていますか。",["人間がドライシャンプーを発明した後","テレビが普及したとき","遠い昔","つい最近"]],"correct":2,"evidence":"Dogs discovered long ago that the best way to protect their food was to bury it.","explanation":"dogs discovered long ago という表現から、遠い昔に身につけた行動だと分かります。"},{"id":"NEW_L10_P2_p6_06","lesson":10,"part":2,"paragraph":6,"difficulty":"Advanced","skill":"Inference","en":["What does the explanation of burying food suggest about the behavior?",["It proves dogs dislike all food stored indoors.","It is mainly a trick dogs learn from people.","It has a practical protective purpose for dogs.","It means dogs are unable to eat fresh food."]],"ja":["食べ物を埋める行動について、この説明から何が分かりますか。",["犬が屋内で保管された食べ物をすべて嫌う証拠である","主に人間から教わった芸である","犬にとって実用的な食べ物の保護目的がある","犬が新鮮な食べ物を食べられないという意味だ"]],"correct":2,"evidence":"the best way to protect their food was to bury it","explanation":"単なるいたずらではなく、食べ物を守るという犬にとって合理的な目的があると読み取れます。"},{"id":"NEW_L10_P2_p6_07","lesson":10,"part":2,"paragraph":6,"difficulty":"Standard","skill":"Comparison","en":["What contrast between people and dogs does the paragraph emphasize?",["People can smell food, but dogs cannot.","They have different reactions to food that has been in the ground.","Only people have ever buried food.","People prefer hot weather, but dogs prefer cold weather."]],"ja":["この段落で強調される人と犬の違いは何ですか。",["人間は食べ物の匂いが分かるが犬には分からない","地中にあった食べ物に対する反応が異なる","食べ物を埋めるのは人間だけだ","人間は暑さを好むが犬は寒さを好む"]],"correct":1,"evidence":"People would not like to eat snacks that have been in the ground, but dogs would not mind doing this.","explanation":"地面にあったおやつを人は嫌うが、犬は気にしないという種による違いを強調しています。"},{"id":"NEW_L10_P3_p7_01","lesson":10,"part":3,"paragraph":7,"difficulty":"Basic","skill":"Detail","en":["How many bones does the author suggest giving a dog that likes to bury them?",["Three every day.","As many as it can carry.","Just one.","None under any circumstances."]],"ja":["骨を埋めることが好きな犬には骨をいくつ与えるとよいですか。",["毎日３つ","持ち運べるだけたくさん","１つだけ","どんな場合も１つも与えない"]],"correct":2,"evidence":"If a dog likes to bury bones in the yard, give him just one.","explanation":"骨を埋めるのが好きな犬には、骨を1つだけ与えると提案しています。"},{"id":"NEW_L10_P3_p7_02","lesson":10,"part":3,"paragraph":7,"difficulty":"Standard","skill":"CauseEffect","en":["What will a dog probably do if it receives only one bone?",["Trade it for several cookies.","Keep it nearby and guard it.","Bury it immediately and forget it.","Give it to a passing stranger."]],"ja":["骨を1つだけ与えられると、犬はどうする可能性が高いですか。",["何枚かのクッキーと交換する","近くに置いて守る","すぐに埋めて忘れる","通りかかった見知らぬ人に渡す"]],"correct":1,"evidence":"With just one, he will probably keep it nearby and guard it.","explanation":"骨が1つだけなら近くに置いて守るだろう、と本文は述べています。"},{"id":"NEW_L10_P3_p7_03","lesson":10,"part":3,"paragraph":7,"difficulty":"Basic","skill":"Detail","en":["What should an owner stop giving a dog that hides cookies?",["Cookies.","Water.","Fresh air.","A place to sleep."]],"ja":["クッキーを隠す犬には、飼い主は何を与えるのをやめるべきですか。",["クッキー","水","新鮮な空気","眠る場所"]],"correct":0,"evidence":"So stop giving them to him.","explanation":"クッキーを隠す場合は、クッキーを与えるのをやめるよう提案しています。"},{"id":"NEW_L10_P3_p7_04","lesson":10,"part":3,"paragraph":7,"difficulty":"Standard","skill":"Inference","en":["Why might a dog hide cookies, according to the author?",["It regards them as food saved for later.","It wants to make cookies disappear forever.","It wants to teach people how to bake.","It believes the cookies are dangerous to its owner."]],"ja":["犬がクッキーを隠す理由として筆者は何を挙げていますか。",["後で食べるために残しておく食べ物だと考えている","クッキーを永久に消したいと思っている","人間にお菓子の焼き方を教えたいと思っている","クッキーが飼い主にとって危険だと信じている"]],"correct":0,"evidence":"he is treating them as leftover food for the future","explanation":"犬はクッキーを、将来に備えて残しておく食べ物として扱っていると説明されています。"},{"id":"NEW_L10_P3_p7_05","lesson":10,"part":3,"paragraph":7,"difficulty":"Basic","skill":"Detail","en":["According to this paragraph, can dogs do without several snacks every day?",["No, every dog must eat snacks several times daily.","Only when owners also stop eating meals.","Yes, dogs can be fine without them.","Only if the snacks are buried first."]],"ja":["犬は1日に何度もおやつを食べなくても大丈夫だとされていますか。",["いいえ、すべての犬は毎日何度もおやつを食べる必要があります","飼い主も食事をやめた場合に限ります","はい、なくても問題ありません","先におやつを埋めた場合に限ります"]],"correct":2,"evidence":"dogs will be fine without them.","explanation":"犬は人のように1日に何度もおやつを食べなくても大丈夫だと述べています。"},{"id":"NEW_L10_P3_p7_06","lesson":10,"part":3,"paragraph":7,"difficulty":"Standard","skill":"Comparison","en":["How are people and dogs compared in relation to frequent snacking?",["Dogs need more snacks than people do.","Both must have cookies after every meal.","Neither people nor dogs ever enjoy snacks.","People may enjoy frequent snacks, but dogs do not need them."]],"ja":["頻繁におやつを食べることについて、人と犬はどう比較されていますか。",["犬は人間より多くのおやつが必要である","両方とも毎食後クッキーが必要である","人間も犬もおやつを楽しむことは決してない","人間は何度もおやつを楽しむことがあるが、犬には必要ない"]],"correct":3,"evidence":"People may like eating snacks several times a day, but dogs will be fine without them.","explanation":"人は頻繁なおやつを好む場合がありますが、犬には必須ではないという対比です。"},{"id":"NEW_L10_P3_p7_07","lesson":10,"part":3,"paragraph":7,"difficulty":"Advanced","skill":"Application","en":["Which plan best follows both suggestions in this paragraph?",["Bury several bones for the dog before breakfast.","Offer cookies every hour to stop food hiding.","Offer one bone and stop giving cookies if the dog hides them.","Give many bones and leave cookies around the yard."]],"ja":["第7段落の2つの提案を両方実行するにはどうするべきですか。",["朝食前に犬のために骨を何本も埋める","食べ物を隠さないよう毎時間クッキーを与える","骨を１つだけ与え、犬がクッキーを隠すなら与えるのをやめる","骨をたくさん与え、庭にクッキーを放置する"]],"correct":2,"evidence":"If a dog likes to bury bones in the yard, give him just one.","explanation":"「骨は1つだけ」「クッキーを隠すなら与えない」という2つの提案を同時に守っています。"},{"id":"NEW_L10_P3_p8_01","lesson":10,"part":3,"paragraph":8,"difficulty":"Basic","skill":"Detail","en":["What do some dogs do when owners begin filling a bath with water?",["Bring their owners a towel.","Disappear and hide.","Run outside to bury a bone.","Jump into the bath immediately."]],"ja":["飼い主がお風呂に水を入れ始めると、一部の犬はどうしますか。",["飼い主にタオルを持ってくる","姿を消して隠れる","外へ走って骨を埋める","すぐにお風呂に飛び込む"]],"correct":1,"evidence":"my dog disappears and hides","explanation":"飼い主が浴槽に水を入れ始めると、犬が隠れてしまうと述べられています。"},{"id":"NEW_L10_P3_p8_02","lesson":10,"part":3,"paragraph":8,"difficulty":"Basic","skill":"Detail","en":["What might a dog do immediately after a bath?",["Rub itself against beds or roll on the carpet.","Sit quietly until completely dry.","Hide every piece of furniture.","Begin guarding the mail carrier."]],"ja":["犬は入浴直後にどんな行動を取ることがありますか。",["ベッドに体をこすりつけたり、カーペットの上で転がったりする","完全に乾くまで静かに座っている","家具をすべて隠す","郵便配達人を見張り始める"]],"correct":0,"evidence":"rub himself up against beds, roll on the carpet","explanation":"入浴後にベッドに体をこすりつけたり、カーペットで転がったりすると説明されています。"},{"id":"NEW_L10_P3_p8_03","lesson":10,"part":3,"paragraph":8,"difficulty":"Standard","skill":"CauseEffect","en":["Why does a dog rub against furniture after bathing, according to the passage?",["To make the furniture smell like shampoo.","To remove every trace of dust from the room.","To get back its natural dog smell.","To tell the owner that it wants more food."]],"ja":["犬が入浴後に家具へ体をこすりつけるのはなぜですか。",["家具をシャンプーの匂いにするため","部屋のほこりをすべて取り除くため","犬本来の匂いを取り戻すため","もっと食べ物が欲しいと飼い主に伝えるため"]],"correct":2,"evidence":"He is trying to get back his \"dog smell.\"","explanation":"犬は洗い流された自分本来の犬の匂いを取り戻そうとしている、と説明されています。"},{"id":"NEW_L10_P3_p8_04","lesson":10,"part":3,"paragraph":8,"difficulty":"Standard","skill":"CauseEffect","en":["Why can being wet help a dog restore its natural smell?",["Wet fur automatically produces baby powder.","Wet fur can collect more dust and dirt.","Water stops the dog from smelling anything.","A wet dog is unable to move around."]],"ja":["濡れた状態が本来の匂いを取り戻す助けになるのはなぜですか。",["濡れた毛が自動的にベビーパウダーを作るから","濡れた毛にはほこりや汚れがより多く付着するから","水によって犬は何の匂いも感じなくなるから","濡れた犬は動き回れないから"]],"correct":1,"evidence":"While he is wet, he can pick up more dust and dirt, which will help bring back his smell.","explanation":"濡れた状態では、ほこりや汚れが付着しやすくなり、自分の匂いを取り戻す助けになります。"},{"id":"NEW_L10_P3_p8_05","lesson":10,"part":3,"paragraph":8,"difficulty":"Standard","skill":"Contrast","en":["How do owners and dogs differ in their preferences about smell?",["Dogs prefer to smell exactly like humans.","Both prefer the strong smell of baby powder.","Owners want more dirt, while dogs want perfume.","Owners prefer a clean fresh smell, while dogs prefer their natural scent."]],"ja":["匂いについて、飼い主と犬の好みはどう違いますか。",["犬は人間と全く同じ匂いになりたがる","両方ともベビーパウダーの強い匂いを好む","飼い主はもっと汚れを好み、犬は香水を好む","飼い主は清潔で爽やかな匂いを好むが、犬は自分本来の匂いを好む"]],"correct":3,"evidence":"Dogs prefer their natural scent.","explanation":"飼い主は清潔で爽やかな匂いを望みますが、犬は自然な自分の匂いを好みます。"},{"id":"NEW_L10_P3_p8_06","lesson":10,"part":3,"paragraph":8,"difficulty":"Basic","skill":"VocabularyInContext","en":["What does \"scent\" most nearly mean in the final sentence?",["Size.","Speed.","Sound.","Smell."]],"ja":["最後の文の scent に最も近い意味は何ですか。",["大きさ","速さ","音","匂い"]],"correct":3,"evidence":"Dogs prefer their natural scent.","explanation":"scent は匂い・香りを表し、ここでは犬本来の匂いを意味します。"},{"id":"NEW_L10_P3_p8_07","lesson":10,"part":3,"paragraph":8,"difficulty":"Advanced","skill":"Inference","en":["Why might a freshly washed dog behave in a way that frustrates its owner?",["The dog wants to prove it can wash furniture.","The dog believes baths help food last longer.","The dog is trying to teach its owner to swim.","The dog tries to restore a smell the owner wanted to wash away."]],"ja":["洗い立ての犬が飼い主を困らせる行動を取るのはなぜだと考えられますか。",["家具を洗えると証明したいから","入浴すると食べ物が長持ちすると信じているから","飼い主に泳ぎ方を教えようとしているから","飼い主が洗い落としたかった匂いを、犬が取り戻そうとするから"]],"correct":3,"evidence":"He is trying to get back his \"dog smell.\"","explanation":"飼い主が落としたい匂いを犬は取り戻そうとするため、同じ行動への目的がすれ違います。"},{"id":"NEW_L10_P4_p9_01","lesson":10,"part":4,"paragraph":9,"difficulty":"Basic","skill":"Detail","en":["Which two ingredients does the author suggest for a dry shampoo?",["Sand and soap bubbles.","Vinegar and orange juice.","Cornstarch and baby powder.","Salt and cooking oil."]],"ja":["ドライシャンプーの材料として挙げられている2つは何ですか。",["砂と石けんの泡","酢とオレンジジュース","コーンスターチとベビーパウダー","塩と食用油"]],"correct":2,"evidence":"using cornstarch and baby powder","explanation":"本文ではドライシャンプーの材料として、コーンスターチとベビーパウダーを挙げています。"},{"id":"NEW_L10_P4_p9_02","lesson":10,"part":4,"paragraph":9,"difficulty":"Basic","skill":"Detail","en":["What is the baby powder supposed to remove from the dog’s fur?",["Bones.","Grass seeds.","Water from the bath.","Oil."]],"ja":["ベビーパウダーは犬の毛から何を取り除くために使いますか。",["骨","草の種","入浴時の水","油分"]],"correct":3,"evidence":"Baby powder will clean oil off the dog's fur.","explanation":"ベビーパウダーは犬の毛から油分を取り除くために使うと説明されています。"},{"id":"NEW_L10_P4_p9_03","lesson":10,"part":4,"paragraph":9,"difficulty":"Standard","skill":"CauseEffect","en":["Why is cornstarch added to the mixture?",["To reduce the smell of the baby powder.","To encourage the dog to roll on the carpet.","To make the shampoo smell stronger.","To increase the amount of oil on the fur."]],"ja":["混ぜ物にコーンスターチを加えるのはなぜですか。",["ベビーパウダーの匂いを弱めるため","犬にカーペットの上で転がるよう促すため","シャンプーの匂いを強くするため","毛の油分を増やすため"]],"correct":0,"evidence":"Cornstarch will weaken the smell of the baby powder.","explanation":"コーンスターチはベビーパウダーの匂いを弱める役割をもつと書かれています。"},{"id":"NEW_L10_P4_p9_04","lesson":10,"part":4,"paragraph":9,"difficulty":"Basic","skill":"Detail","en":["How should the dry-shampoo mixture be applied?",["Scatter it on the lawn.","Pour it into the dog’s food.","Put it into the bath water only.","Brush it into the dog’s coat."]],"ja":["ドライシャンプーの混ぜ物はどう使うべきですか。",["芝生にまく","犬の餌に入れる","浴槽のお湯にだけ入れる","ブラシで犬の毛にすり込む"]],"correct":3,"evidence":"Brush this mixture into the dog's coat to clean him.","explanation":"作った混合物を犬の毛にブラシでなじませると説明しています。"},{"id":"NEW_L10_P4_p9_05","lesson":10,"part":4,"paragraph":9,"difficulty":"Basic","skill":"Detail","en":["What is the second proposed solution after a dog takes a bath?",["Turn on loud construction equipment.","Give the dog many cookies.","Make the dog look through a window.","Take the dog for a walk right away."]],"ja":["犬の入浴後の問題への2つ目の解決策は何ですか。",["大きな音の建設機械を動かす","犬にクッキーをたくさん与える","犬に窓の外を見せる","入浴後すぐに犬を散歩に連れていく"]],"correct":3,"evidence":"take the dog for a walk right after he leaves the bath","explanation":"もう1つの方法は、入浴した直後に犬を散歩へ連れていくことです。"},{"id":"NEW_L10_P4_p9_06","lesson":10,"part":4,"paragraph":9,"difficulty":"Standard","skill":"CauseEffect","en":["How does an immediate walk help after bathing?",["It makes the dog’s fur permanently wet.","It distracts the dog from removing the fresh smell and lets it dry.","It teaches the dog to make shampoo.","It forces the dog to avoid every outdoor smell."]],"ja":["入浴直後の散歩にはどのような効果がありますか。",["犬の毛を永久に濡れた状態にする","爽やかな匂いを消すことから犬の気をそらし、乾かすこともできる","犬にシャンプーの作り方を教える","屋外の匂いを一切かがせない"]],"correct":1,"evidence":"This will make the dog forget about getting rid of that fresh smell. Also, the dog will become dry during the walk.","explanation":"散歩は爽やかな匂いを消すことから犬の注意をそらし、体を乾かす助けにもなります。"},{"id":"NEW_L10_P4_p9_07","lesson":10,"part":4,"paragraph":9,"difficulty":"Advanced","skill":"Comparison","en":["What do the two bathing solutions have in common?",["They try to make cleaning easier without ignoring the dog’s preferences.","They rely on washing the dog more often in strong perfume.","They both prevent the dog from ever going outside.","They both require the dog to eat less food."]],"ja":["この段落に示された2つの入浴後の対策に共通する考え方は何ですか。",["犬の好みを無視せずに、清潔に保ちやすくしようとしている","強い香水で犬をより頻繁に洗うことに頼る","どちらも犬が二度と外に出られないようにする","どちらも犬の食事量を減らす必要がある"]],"correct":0,"evidence":"There are two ways to solve this problem.","explanation":"パウダーの匂いを弱める工夫と、犬が好きな散歩で気をそらす工夫のどちらも、犬の習性を考慮した対策です。"},{"id":"NEW_L10_P4_p10_01","lesson":10,"part":4,"paragraph":10,"difficulty":"Basic","skill":"Detail","en":["Why does a person usually keep a dog, according to the passage?",["To teach the dog to cook meals.","To stop all strangers from visiting.","To make personal and family life happier.","To avoid making any human friends."]],"ja":["本文によると、人が普通犬を飼うのはなぜですか。",["犬に料理を教えるため","見知らぬ人が訪ねてくるのをすべて防ぐため","自分や家族の生活をもっと幸せにするため","人間の友人を一切作らないため"]],"correct":2,"evidence":"A person usually keeps a dog to make his or her life, and family, happier.","explanation":"飼う目的として、自分自身や家族の生活をより幸せにすることが挙げられています。"},{"id":"NEW_L10_P4_p10_02","lesson":10,"part":4,"paragraph":10,"difficulty":"Basic","skill":"Detail","en":["What does an owner also want for a pet living with people?",["For the pet to leave the family permanently.","For the pet to learn to use computers.","For the pet to enjoy its life in a human environment.","For the pet to stop acting like an animal."]],"ja":["犬を飼う人は、犬が人間と暮らすうえで何を望んでいますか。",["ペットが家族のもとから永久に去ること","ペットがコンピューターを使えるようになること","人間の生活環境の中でペットが楽しく暮らせること","ペットが動物らしい行動をやめること"]],"correct":2,"evidence":"an owner wants his or her animal to enjoy living in a human environment.","explanation":"飼い主は犬にも人間の環境での暮らしを楽しんでほしいと望んでいます。"},{"id":"NEW_L10_P4_p10_03","lesson":10,"part":4,"paragraph":10,"difficulty":"Standard","skill":"CauseEffect","en":["What do people sometimes forget about dogs?",["They cannot learn any habits at all.","They belong to a species different from humans.","They always want the same scent as people.","They prefer living without any social contact."]],"ja":["人が犬について時々忘れてしまうことは何ですか。",["どんな習慣も全く学習できないこと","人間とは異なる種の動物であること","常に人間と同じ匂いになりたがること","社会との接触がない生活を好むこと"]],"correct":1,"evidence":"dogs are a totally different species from us","explanation":"犬が人間とはまったく異なる種であるという事実を忘れがちだと述べています。"},{"id":"NEW_L10_P4_p10_04","lesson":10,"part":4,"paragraph":10,"difficulty":"Standard","skill":"Inference","en":["Why does the writer compare dogs to visitors from a foreign country?",["To explain that dogs understand different human languages.","To encourage owners to respect unfamiliar ways of behaving.","To argue that dogs should be given passports.","To suggest that pets should live abroad."]],"ja":["筆者が犬を外国から来た存在にたとえるのはなぜですか。",["犬が異なる人間の言語を理解できると説明するため","慣れない行動様式を飼い主が尊重するよう促すため","犬にパスポートを発行するべきだと論じるため","ペットは外国で暮らすべきだと提案するため"]],"correct":1,"evidence":"think of our pets as if they came from a foreign country","explanation":"外国の人の習慣を理解しようとするように、人間とは異なる犬の習性を尊重すべきだという比喩です。"},{"id":"NEW_L10_P4_p10_05","lesson":10,"part":4,"paragraph":10,"difficulty":"Basic","skill":"Detail","en":["What does the author say is important at the end?",["More frequent shampooing.","Cross-species understanding.","Bigger and more expensive houses.","Perfectly silent dogs."]],"ja":["本文の最後で筆者が重要だと述べていることは何ですか。",["より頻繁なシャンプー","異なる種どうしが理解し合うこと","より大きく高価な家","全く吠えない犬"]],"correct":1,"evidence":"Cross-species understanding is important.","explanation":"最後の一文に「異種間の理解が重要」と明記されています。"},{"id":"NEW_L10_P4_p10_06","lesson":10,"part":4,"paragraph":10,"difficulty":"Advanced","skill":"MainIdea","en":["Which statement best expresses the overall message of the passage?",["Understanding dogs’ natural behavior helps people live with them better.","Dogs should always be treated exactly like human children.","Most dog problems can be solved by buying new furniture.","Every undesirable dog habit should be punished immediately."]],"ja":["本文全体の中心的な主張として最も適切なものはどれですか。",["犬本来の行動を理解すると、人は犬とより良く暮らせる","犬は常に人間の子どもと全く同じように扱うべきだ","犬の問題はほとんど新しい家具を買えば解決する","犬の好ましくない習慣はすぐにすべて罰するべきだ"]],"correct":0,"evidence":"To get along better with dogs, we should try to think of our pets as if they came from a foreign country","explanation":"吠える・食べ物を埋める・入浴後の行動などの理由を理解し、犬とうまく暮らすことが本文全体の主張です。"},{"id":"NEW_L10_P4_p10_07","lesson":10,"part":4,"paragraph":10,"difficulty":"Advanced","skill":"Application","en":["Which action best reflects the idea of cross-species understanding?",["Ignore the dog’s needs as long as the owner is happy.","Ask why a dog behaves a certain way before deciding how to respond.","Punish a dog every time it follows a natural habit.","Assume every dog should react like a human child."]],"ja":["「異種間の理解」という考え方を最もよく反映する行動はどれですか。",["飼い主が幸せなら犬の必要なことは無視する","どう対応するか決める前に、犬がなぜそのように行動するかを考える","自然な習性に従うたびに犬を罰する","どの犬も人間の子どもと同じ反応をするはずだと思う"]],"correct":1,"evidence":"Cross-species understanding is important.","explanation":"犬の立場から行動の理由を理解したうえで対応を考えることが、異種間理解という結論に合います。"}];})(typeof globalThis!=="undefined"?globalThis:this);
